#!/usr/bin/env python3
"""PandorumLLM release gate - run on the staging copy, blocks packaging.

    python3 gate.py [tree]

Implements DEVELOPMENT.md section 8. Every check here must be capable of failing:
a check that confirms a function *exists* is not a check (section 8), and a check
built from the thing it tests cannot fail (gotcha 17). Where a check cannot be run
in this environment it is reported as SKIP, never as a pass.

Line-ending and per-line checks read bytes, never text mode - universal newlines
collapse CRLF on read and make such a check silently examine nothing (gotcha 18).
"""
import base64
import io
from urllib.error import HTTPError
import os
import re
import sys
import ast
import json
import shutil
import struct
import hashlib
import socket
import string
import subprocess
import tempfile
import importlib.util
import collections
import builtins
import threading
import time

ROOT = os.path.abspath(sys.argv[1] if len(sys.argv) > 1 else ".")

# ONE SCRATCH ROOT PER RUN, gone however the run ends. Runtimes made temp
# directories where they pleased and removed them in finally blocks - which a
# GateBug, a plant that aborted the run, or timeout's SIGABRT never reached.
# 134,000 orphaned folders filled the disk mid-ritual at patch135. Everything
# tempfile makes now lands under this one folder, and it is removed at exit
# AND on the signals that would otherwise skip exit. (p141)
import atexit
import signal
import faulthandler
# a segfault, an abort from C, a bus error: each prints its Python stack to
# stderr instead of vanishing. A run that still dies with nothing on stderr
# after this has been killed from outside with SIGKILL - which is a diagnosis,
# not a mystery. (p145)
faulthandler.enable(all_threads=True)
import tempfile as _tf_root
SCRATCH = _tf_root.mkdtemp(prefix="gate-%d-" % os.getpid())
_tf_root.tempdir = SCRATCH


def _scratch_gone(*_a):
    import shutil as _sh
    if _a:                                # called as a signal handler: say so, and where
        try:
            import traceback as _tb
            sys.stderr.write("\nGATE: signal %r received in section %r\n" % (_a[0], _section))
            _tb.print_stack(_a[1], file=sys.stderr)
            sys.stderr.flush()
        except Exception:
            pass
    _sh.rmtree(SCRATCH, ignore_errors=True)
    if _a:
        os._exit(1)


atexit.register(_scratch_gone)


# WHERE JSDOM LIVES. Three runtimes drove node from a folder an earlier session
# had set up by hand (/tmp/dom) - a dependency on the environment that nothing
# in the gate declared, found the day the container restarted and the folder
# was gone. The gate resolves it now: any folder from which node can require
# jsdom, installing it under the tools folder if none can, and a runtime that
# still cannot find it reports a named skip rather than a crash. (p143)
def _find_jsdom():
    import subprocess as _sp
    cands = ["/home/claude/tools/dom", "/tmp/dom", os.path.expanduser("~/dom")]
    for c in cands:
        if os.path.isdir(c):
            try:
                r = _sp.run(["node", "-e", "require('jsdom')"], cwd=c,
                            capture_output=True, timeout=30)
                if r.returncode == 0:
                    return c
            except Exception:
                pass
    try:
        os.makedirs(cands[0], exist_ok=True)
        r = _sp.run(["npm", "install", "--silent", "--no-audit", "--no-fund", "jsdom@24"],
                    cwd=cands[0], capture_output=True, timeout=300)
        if r.returncode == 0:
            return cands[0]
    except Exception:
        pass
    return None


JSDOM_CWD = _find_jsdom()
for _sig in ("SIGABRT", "SIGTERM", "SIGINT"):
    if hasattr(signal, _sig):
        signal.signal(getattr(signal, _sig), _scratch_gone)
FAIL, SKIP = [], []
_section = ""


# A SECTION LEAVES THE PANEL AS IT FOUND IT. 49 sections replaced fp.log_dir,
# fp.panel_log, fp.load_config and friends with stand-ins for their own scratch
# folders and never put them back, so every section after the first of them
# was testing a lambda pointing at a deleted directory - and the p142 lock
# probe passed with the p123 deadlock planted, because it never touched the
# real function. Rather than 49 restores, one rule: every section starts from
# the module as it was loaded. The snapshot is taken on the first section after
# fp exists; each section() call puts back every attribute that has been
# replaced, and reports how many it had to. (p145)
_FP_PRISTINE = None
_FP_RESTORED = []


def _fp_restore():
    global _FP_PRISTINE
    fpm = globals().get("fp")
    if fpm is None:
        return
    if _FP_PRISTINE is None:
        _FP_PRISTINE = {k: getattr(fpm, k) for k in dir(fpm) if not k.startswith("__")}
        return
    put_back = []
    for k, v in _FP_PRISTINE.items():
        if getattr(fpm, k, _FP_PRISTINE) is not v:
            setattr(fpm, k, v)
            put_back.append(k)
    if put_back:
        _FP_RESTORED.append((_section, put_back))


_TRACE_SEEN = set()


def _trace_watch():
    """Name the section that left a trace, at the boundary where it first shows.
    The end-of-run check says THAT the tree was dirtied; this says WHO. (p145)"""
    # the tree had none of these when the run began (the opening sweep insists),
    # so any that appear are the gate's own; each is named and removed, so ONE
    # run names EVERY section that leaves one rather than the first
    for nm in ("logs", "fleet-config.json", "__pycache__", "model-kinds.json", "Models", "models",   # the model homes (patch16)
               "tts-model-kinds.json", "decision-models.json"):   # shipped through p175 (p177); the scan's (p60)
        p = os.path.join(ROOT, nm)
        if os.path.exists(p):
            # before the first section there is no culprit: the file was in the
            # tree when the run began - committed, or left by an earlier run (p177)
            _TRACE_SEEN.add((nm, _section or "the tree as the run began"))
            print("  !! %s %s" % (nm, "appeared in the tree during section %r" % _section
                  if _section else "was in the tree when the run began"))
            shutil.rmtree(p, ignore_errors=True) if os.path.isdir(p) else os.remove(p)


def section(name):
    global _section
    _trace_watch()
    _fp_restore()
    _section = name
    print("\n== %s ==" % name)


def check(ok, label, detail=""):
    if isinstance(ok, Exception):        # a broken check is a failure, not a pass
        FAIL.append((_section, "GATE BUG: " + label, str(ok)))
        print("  FAIL GATE BUG: %s - %s" % (label, ok))
        return
    if ok is None:
        SKIP.append((_section, label, detail))
        print("  SKIP %s %s" % (label, detail))
    elif ok:
        print("  ok   %s" % label)
    else:
        FAIL.append((_section, label, detail))
        print("  FAIL %s %s" % (label, detail))


class GateBug(Exception):
    """The gate itself is broken, as distinct from the code under test being wrong."""


def defined(text, name):
    """Is `name` DEFINED in text - assigned or def'd at line start - rather than
    merely mentioned? A short identifier as a whole-file needle matched any
    comment that named it; a control that removed the definition passed on the
    comment explaining why it must exist. (p141)"""
    return re.search(r"^\s*(?:def\s+%s\s*\(|%s\s*=)" % (re.escape(name), re.escape(name)),
                     text, re.M) is not None


def before(text, a, b):
    """Is a written before b, with BOTH actually present?

    str.index raises when its needle is absent, and a negative control's whole
    job is to remove needles - so an ordering check written with index() kills
    the entire run at that line the moment a plant lands, hiding every check
    after it. find() alone is worse than useless: -1 < 5 is true, so a missing
    needle would make the check PASS.

    Five sections have now hit this, the first at patch124 - where I wrote that
    remembering it per section had not worked, and then went on remembering it
    per section. (p132)
    """
    i = text.find(a)
    j = text.find(b)
    return 0 <= i < j


def seg(text, start, end, nth=1):
    """The text between two anchors - or a loud failure.

    EVERY silent gate failure this project has had came from this one operation going
    wrong. An anchor that also matched a longer name; an end anchor occurring BEFORE the
    start, so Python returned an empty string; two anchors that had drifted adjacent.
    And an empty string satisfies every "must NOT contain" check ever written - so a
    broken slice did not fail, it passed, having tested nothing at all.

    So: the start anchor must be unique (or say which occurrence you meant), the end is
    only searched for AFTER the start, and a suspiciously short result is an error.
    """
    n = text.count(start)
    if n == 0:
        raise GateBug("start anchor not found: %r" % (start[:70],))
    if n > 1 and nth == 1:
        raise GateBug("start anchor %r matches %d places - use a longer anchor, or nth="
                      % (start[:70], n))
    if nth > n:
        raise GateBug("start anchor %r has %d matches, asked for #%d"
                      % (start[:50], n, nth))
    a = -1
    for _ in range(nth):
        a = text.index(start, a + 1)
    b = text.find(end, a + len(start))          # AFTER the start: never backwards
    if b < 0:
        raise GateBug("end anchor %r never appears after start %r"
                      % (end[:60], start[:60]))
    out = text[a:b]
    if len(out) < 24:
        raise GateBug("slice %r .. %r is only %d chars - the anchors have drifted together"
                      % (start[:40], end[:40], len(out)))
    return out


# patch47 nests every field audio.cpp reads from its "options" object; the older checks below were written
# to the flat shape and ask "which fields, under which names" - flat47 folds options back so they still ask it
def flat47(req):
    r = dict(req or {}); r.update(r.pop("options", {}) or {})
    return r
def flatbody47(body):
    b = dict(body or {}); b["request"] = flat47(b.get("request")); return b

_Q3 = chr(34) * 3
_A3 = chr(39) * 3
_DOC_RX = [re.compile(_Q3 + r"[\s\S]*?" + _Q3), re.compile(_A3 + r"[\s\S]*?" + _A3)]


def code_only(text):
    """Source with comments and docstrings removed.

    A check that greps for a symbol will otherwise match the comment explaining why that
    symbol must not be used. That has happened four times in this project.
    """
    for rx in _DOC_RX:
        text = rx.sub('""', text)
    keep = []
    for line in text.split("\n"):
        s = line.lstrip()
        if s.startswith("#") or s.startswith("//"):
            continue
        keep.append(line)
    return "\n".join(keep)



def seg_len(text, start, n, nth=1):
    """A fixed number of characters from an anchor, with the same anchor checks as seg()."""
    c = text.count(start)
    if c == 0:
        raise GateBug("start anchor not found: %r" % (start[:70],))
    if c > 1 and nth == 1:
        raise GateBug("start anchor %r matches %d places - use a longer anchor, or nth="
                      % (start[:70], c))
    a = -1
    for _ in range(nth):
        a = text.index(start, a + 1)
    out = text[a:a + n]
    if len(out) < min(n, 24):
        raise GateBug("slice from %r is only %d chars" % (start[:40], len(out)))
    return out



def _anchor_at(text, start, nth=1):
    c = text.count(start)
    if c == 0:
        raise GateBug("anchor not found: %r" % (start[:70],))
    if c > 1 and nth == 1:
        raise GateBug("anchor %r matches %d places - use a longer anchor, or nth="
                      % (start[:70], c))
    a = -1
    for _ in range(nth):
        a = text.index(start, a + 1)
    return a


def seg_before(text, start, n, nth=1):
    """The n characters BEFORE an anchor - the window a handler's dispatch sits in."""
    a = _anchor_at(text, start, nth)
    out = text[max(0, a - n):a]
    if len(out) < min(n, 24):
        raise GateBug("only %d chars precede %r" % (len(out), start[:40]))
    return out


def seg_around(text, start, before, after, nth=1):
    """A window either side of an anchor."""
    a = _anchor_at(text, start, nth)
    out = text[max(0, a - before):a + after]
    if len(out) < 24:
        raise GateBug("window around %r is only %d chars" % (start[:40], len(out)))
    return out


def seg_from(text, start, nth=1):
    """Everything from an anchor to the end, with the anchor still validated."""
    a = _anchor_at(text, start, nth)
    out = text[a:]
    if len(out) < 24:
        raise GateBug("only %d chars follow %r" % (len(out), start[:40]))
    return out


def nin(segment, needle, label, detail=""):
    """A must-NOT-contain check that first proves it is looking at something.

    This is the shape that used to pass silently: `"x" not in <empty string>` is True.
    """
    if not segment or len(segment) < 24:
        check(GateBug("segment is empty or trivial (%d chars)" % len(segment or "")), label)
        return
    check(needle not in segment, label, detail)


def rd(rel):
    with open(os.path.join(ROOT, rel), "rb") as f:
        return f.read()


# --------------------------------------------------------------- 1. file set
section("file set")

SHIPPED = ["fleet-panel.py", "README.txt", "PandorumLLM.exe", "PandorumLLM.ico",
           "force-stop.bat", "StartPandorumLLM.bat", "launch-llm-fleet.ps1", "launcher-template.ps1",
           "fleet-config.default.json", "templates/single-gpu.ps1",
           "server-templates/pinned-server.ps1",
           "ps1-launchers/README.txt", "launcher-src/launcher.cpp",
           "launcher-src/app.rc", "launcher-src/app.manifest",
           "launcher-src/PandorumLLM.ico", "LICENSE"]
