check('"ttsEngine"' not in seg(py, "DEF_SETTINGS = {", "\n}")
      and 'for _mk in ("ttsEngine", "ttsServerExe", "ttsModel", "ttsPython", "ttsWrapper"):' in py,
      "there is no engine to default - a config that names one has it, and the proxy's settings, dropped on load")

