    _spec = [x for x in fp.SERVER_PARAMS if x[0] == _k]
    check(len(_spec) == 1, "a caution names a dial that exists: %s" % _k)
    for _v in _vals:
        check(_v in (_spec[0][4].get("opts") or []),
              "and a value that dial can stand on: %s=%s" % (_k, _v))
