def _tagout(settings, who, answer):
    for _f in os.listdir(_tagdir):
        os.remove(os.path.join(_tagdir, _f))
    fp.tag_output_line(who, answer, {"settings": settings})
    _got = ""
    for _f in os.listdir(_tagdir):
        _got = open(os.path.join(_tagdir, _f), encoding="utf-8").read()
    return _got


