check('_kill_port_owner' in seg(seg(py, "def _api_tts_server(body, _retry=False):", "def api_launcher_content(body):"), 'if action == "stop":', 'if action != "start":'),   # scoped to the TTS server's own handler since the song server has one too (v3.80 patch2)
      "the button still runs the port kill the exit now shares")
