    _base = [_rowG("Good morning to you my friend",
                   fp.VOICE_BASE0 + fp.VOICE_SLOPE0 * 29) for _ in range(8)]
    _sfxr = [_rowG("<|sfx:sigh|>Good morning to you my friend",
                   fp.VOICE_BASE0 + fp.VOICE_SLOPE0 * 29 + 30) for _ in range(8)]
