# ------------------------------------------------------------------ v3.76 patch4
# The card said "the launch stopped after 34s without finishing - last log line:
# resolve_fused_ops: resolving fused Gated Delta Net support:". One line above it sat
# GGML_ASSERT(ggml_can_mul_mat(a, b)), which is the whole diagnosis. Quoting the LAST
# line quotes what a process was doing when it stopped, not why it stopped.
section("v3.76 patch4: a failed launch names its cause")

check("LAUNCH_FAULTS = (" in py and "def launch_fault_cause(" in py,
      "llama.cpp's own words are read for a cause")
check("cause = launch_fault_cause(path)" in py
      and before(py, "cause = launch_fault_cause(path)", '"the launch stopped after %.0fs'),
      "and the cause is preferred over quoting the last line")
check("f.readlines()[-int(tail_lines):]" in py,
      "read from the TAIL, because a crash keeps printing after its reason")
for _n4 in ("ggml_can_mul_mat", "mismatch between text model", "cudaMalloc failed",
            "unknown model architecture", "unable to find tensor",
            "Address already in use"):
    # a membership test, not seg(): a raising pin takes every check below it down,
    # and this one anchored on newlines the file does not spell that way
    check(_n4 in py and "LAUNCH_FAULTS" in py,
          "it knows: %s" % _n4)

try:
    import tempfile as _tf4, os as _os4
    _d4 = _tf4.mkdtemp()
    _p4 = _os4.path.join(_d4, "t.log")

    def _say4(txt):
        _io4 = open(_p4, "w", encoding="utf-8")
        _io4.write(txt); _io4.close()
        return fp.launch_fault_cause(_p4)

    _cases4 = [
        # the assert sits ABOVE the last line, exactly as it did in the field
        ("ggml.c:3282: GGML_ASSERT(ggml_can_mul_mat(a, b)) failed\n"
         "resolve_fused_ops: resolving fused Gated Delta Net support:\n", True),
        ("mtmd_init_from_file: error: mismatch between text model (n_embd = 2560) "
         "and mmproj (n_embd = 1536)\n", True),
        ("cudaMalloc failed: out of memory\n", True),
        ("unknown model architecture: 'clip'\n", True),
        ("srv  init: couldn't bind HTTP server socket, hostname: 127.0.0.1, port: 1236\n", True),   # retold v3.96: llama.cpp's own words
        # a launch that worked must stay silent
        ("srv update_slots: all slots are idle\nserver is listening\n", False),
    ]
    _bad4 = [t[:34] for t, want in _cases4 if bool(_say4(t)) != want]
    try:
        _os4.remove(_p4); _os4.rmdir(_d4)
    except Exception:
        pass
    check(not _bad4,
          "run: an assert above the last line is still found, every named failure is "
          "recognised, and a launch that worked says nothing",
          str(_bad4))
except Exception as _e4x:
    check(False, "the patch4 fault runs did not RUN", str(_e4x)[:140])


# ------------------------------------------------------------------ v3.76 patch5
# stop_tts_server stops the server only when the panel owns it, which is right - a
# server the panel never started belongs to whoever did. But the handle lived in
# memory, so restarting the PANEL made the panel's OWN server foreign to it: still
# running, still on its port, and Terminate walked past it. It already had the code
# to stop a pid without a handle; what it had no way to do was LEARN the pid.
section("v3.76 patch5: the panel keeps its own speech server across a restart")

check(defined(py, "TTS_OWN_FILE") and "def tts_own_write(" in py and "def tts_own_adopt(" in py,
      "a started server leaves a note - pid, port, executable")
check("tts_own_write(p.pid, port, exe)" in py,
      "written where the server is actually started")
check("def tts_own_alive(" in py and "os.path.basename(real) == os.path.basename(exe)" in py,
      "a live pid is not enough - the executable behind it must be the same one")
check('_port_verdict(port, 1.0)[0] != "accepted"' in py,
      "and something must still be answering on the port it claimed")
check(py.count("tts_own_clear()") >= 3,
      "the note is cleared when the server stops and when it is found dead",
      "%d call sites" % py.count("tts_own_clear()"))
check("**NOWIN" in seg(py, "def tts_own_alive(", "def tts_own_adopt("),
      "and the liveness check cannot flash a console")

try:
    import json as _j5, os as _o5, tempfile as _t5
    _d5 = _t5.mkdtemp()
    _old5, fp.TTS_OWN_FILE = fp.TTS_OWN_FILE, _o5.path.join(_d5, "own.json")
    _pl5, fp.panel_log = fp.panel_log, lambda *a, **k: None
    _keep5 = dict(fp.TTS_PROC)

    def _reset5():
        fp.TTS_PROC["pid"], fp.TTS_PROC["proc"] = None, None
        fp.tts_own_clear()

    # no note at all: nothing is adopted
    _reset5()
    _r5a = fp.tts_own_adopt() == ""
    # a note naming a pid that is not this executable is REFUSED, and thrown away
    _reset5()
    fp.tts_own_write(_o5.getpid(), 59999, "definitely-not-this.exe")
    _r5b = (fp.tts_own_adopt() == "" and fp.TTS_PROC.get("pid") is None
            and not _o5.path.isfile(fp.TTS_OWN_FILE))
    # a dead pid is refused too
    _reset5()
    fp.tts_own_write(999999, 59999, "x")
    _r5c = fp.tts_own_adopt() == "" and fp.TTS_PROC.get("pid") is None
    # and a session that already owns one does not adopt over it
    _reset5()
    fp.TTS_PROC["pid"] = 4242
    fp.tts_own_write(_o5.getpid(), 59999, "x")
    _r5d = fp.tts_own_adopt() == ""
    _reset5()
    fp.TTS_OWN_FILE, fp.panel_log = _old5, _pl5
    fp.TTS_PROC.update(_keep5)
    try:
        _o5.rmdir(_d5)
    except Exception:
        pass
    check(_r5a and _r5b and _r5c and _r5d,
          "run: nothing is adopted without a note, a note naming another executable "
          "or a dead pid is refused and discarded, and a session already holding a "
          "server never adopts over it",
          str([_r5a, _r5b, _r5c, _r5d]))
except Exception as _e5x:
    check(False, "the patch5 adoption runs did not RUN", str(_e5x)[:140])


# ------------------------------------------------------------------ v3.76 patch6
# Every terminal receives a finished string and re-derives meaning from it. MARK
# (patch1) unified the vocabulary those guesses are made with; it could not remove
# the guessing, because a painter can see what a line LOOKS like and never what it
# refers to. A reference is carried instead: written by whoever knows what the thing
# is, stripped by whoever paints it, and stable across terminals - the Thinking block
# for call 1236 and the Proxy record for call 1236 wear the same id.
#
# Stage one of three. The remaining producers and the painter migrations follow one
# at a time, because each can silently change what a terminal SHOWS.
section("v3.76 patch6: a record can point at another terminal")

check("def ref_mark(" in py and "REF_KINDS = (" in py,
      "the panel writes a typed reference")
check('ref_mark("dlg", pid)' in py,
      "and the thinking block wears the SAME id the proxy record does")
check("function refTake(" in JS and "function refChip(" in JS
      and "function refJump(" in JS,
      "the page takes it off, shows it, and follows it")
check("const _r = refTake(line, term);" in JS,
      "the Thinking terminal reads it before anything is painted - and reads it "
      "as whichever of the three feeds it is drawing, which it could not say "
      "until patch11")
check('if (d.act === "refJump") { refJump(d.rkind, d.rid); return; }' in JS,
      "and a click on the chip is dispatched")
# one record, one way of showing it
check("function proxyPayloadOpen(pid, view) {" in JS
      and 'if (d.act === "proxyPayload") { proxyPayloadOpen(d.pid, d.view); return; }' in JS,   # a view since p63
      "a reference opens the payload the SAME way the proxy terminal does - two "
      "ways to show one record would drift")

try:
    _L6, _R6 = "\u27e8", "\u27e9"
    _m6 = fp.ref_mark("dlg", 1236)
    _r6 = [
        _m6 == "  " + _L6 + "dlg:1236" + _R6,
        fp.ref_mark("nope", 1) == "",          # an unknown kind writes nothing
        fp.ref_mark("dlg", None) == "",        # and so does a missing id
        fp.ref_mark("dlg", "") == "",
        _m6.strip().startswith(_L6) and _m6.strip().endswith(_R6),
    ]
    check(all(_r6),
          "run: a reference is written for a known kind with an id, and never for "
          "an unknown kind or a missing one",
          str(_r6))
except Exception as _e6x:
    check(False, "the patch6 reference runs did not RUN", str(_e6x)[:140])


