section("v3.76 patch40: the card terminal dies, the allocation report stands up")
# Owner's call: the small launch terminal scrolled too fast to read. Gone -
# markup, state, poll, tail arm, all of it. In its place the VRAM line grew
# into a stacked report: one row per allocator llama.cpp names, each carrying
# a lifecycle - queued, allocating..., then the size - and a dead load keeps
# what landed with dashes for what never did.
nin(JS, "slotTermTick", "the terminal's poll is gone")
nin(JS, "slotLogText", "and the text it hoarded")
nin(JS, '"log-" + ', "and every reach for the pane")
nin(py, 'id="log-', "and the pane itself from the card markup")
_sl40 = seg(py, "def api_slot_log(body):", "\r\ndef ")
# retold p86: it still serves the report and nothing else, but writes the
# allocator record on the way past - once per launch, after it settles
check('return {"report": _rep86}' in _sl40
      and "_rep86 = slot_vram_report(path)" in _sl40,
      "the door serves the report alone, unconditionally")
nin(_sl40, "8192", "no tail window survives in the door")
nin(_sl40, '"log"', "and no log key rides the answer")
check('["weightsGpu", "Weights",' in JS and '["kv",' in JS and '["compGpu",' in JS
      and "x[2] && !r[x[0]]" in JS,
      "the loader's own order is declared once, and the next debt is found in it")
check('"allocating…"' in JS and '"queued"' in JS,
      "the two waiting states wear their names")
check("(r.any || r.exited)" in JS and '"—"' in JS,
      "every attempt persists - after any launch the core rows stay, sized or dashed")
# retold p85: it pins OOM on the row the LOG says failed, and only falls back to
# the row the loader owed when the log did not name one - blaming Compute for a
# failed SWA cache was that fallback being the only rule
check("(oomKey ? key === oomKey : (core && key === nextKey))" in JS
      and 'row(key, lab, "failed" + oomAmt, "vd", "OOM")' in JS,
      "an allocation failure pins OOM on the row the loader owed")
check('llama_kv_cache:\\s+(\\S+) KV buffer size' in py
      and '"oom": False, "final": False, "where": {},' in py
      and 'out["where"].setdefault(_k, [])' in py,
      "the parser keeps the device token of every allocation, and smells an OOM")
check('"cudamalloc failed"' in py and '"not enough memory"' in py,
      "by llama.cpp's own words for running dry")
check("function vramWhere(r, key)" in JS and 'if (key === "mtpCtx") return "VRAM";' in JS
      and 'return gpus.length > 1 ? "VRAM: " + gpus.join("+") : "VRAM";' in JS,
      "device tokens fold to VRAM or RAM, and a split names its GPUs")
check('vramWhere(r, key)' in JS and '.vwhere' in py and '.voom' in py
      and "rgba(255,90,90,.5)" in py,
      "every sized row wears its destination chip, and OOM wears the error ink")
check('row("total", "Total", (about0 ? "\u2248 " : "") + vramVal(sum), "vt", "VRAM")' in JS   # retold v3.91 patch8: about on a pooled card
      and "mib >= 1024 ? vramGiB(mib)" in JS,
      "a total closes the list, and small buffers stay honest MiB")
_vc40 = seg(py, ".vramline {", "pre.log {")
check(".vrow" in _vc40 and ".vlab" in _vc40 and ".vval" in _vc40
      and ".va .vval" in _vc40 and ".vq .vval" in _vc40 and ".vt" in _vc40,
      "rows, labels, values, and the three moods have ink of their own")
check("rgba(77,163,255,.45)" in _vc40,
      "allocating glows in the panel's own accent family")
# retold v3.91 patch1: every card DRAWN asks; one a background refresh left standing has its report
check("if (drew) vramTick(s.id); });" in JS and "slotVramAsked" not in JS,
      "every card render asks each slot for its report - the once-per-page flag "
      "went with the loop that owned it (p46)")
# retold p97: the press starts nothing. The report's own beat already asks for
# every slot that is not final, in one request - and twenty launches used to
# mean twenty extra timers on top of it.
check("setInterval(vramOwnTick, 400);" in JS
      and 'post("/api/slot-logs", { slots: due })' in JS,
      "the press starts the report poll, nothing else")
check("vramTick(sid);        // one last paint" in JS,
      "and the busy-clear paints once more, so waiting rows resolve or vanish")
check("see the allocation report on the card" in JS,
      "the wedged prose points at what exists")
nin(JS, "above the card terminal", "not at what died")
try:
    import subprocess as _sp40
    _a40 = JS.index("function vramGiB")
    _b40 = JS.index("const slotVramEl")
    _h40 = (JS[_a40:_b40]
            .replace("const VRAM_ROWS", "var VRAM_ROWS")
            .replace("const VRAM_TIPS", "var VRAM_TIPS")
            .replace("function vramModel", "var vramModel = function")
            .replace("function vramGiB", "var vramGiB = function")
            .replace("function vramVal", "var vramVal = function")
            .replace("function vramWhere", "var vramWhere = function"))
    _t40 = _h40 + """
var esc = s => String(s);
var slotBusy = { s1: "launch" };\nvar vramAnswered = {}, vramWhy = {};
var rj = m => m.map(x => x.k + ":" + x.val + (x.dest ? ">" + x.dest : "")).join("|");
var z = {weightsGpu:0,mmprojGpu:0,draftGpu:0,kv:0,kvDraft:0,rs:0,compGpu:0,
         mtpCtx:0,weightsHost:0,compHost:0,draftHost:0,freeAtLoad:0,
         any:false,exited:false,oom:false,where:{}};
var t1 = rj(vramModel("s1", Object.assign({}, z)));
var t2 = rj(vramModel("s1", Object.assign({}, z, {any:true, weightsGpu:14540})));
var t4 = rj(vramModel("s1", Object.assign({}, z, {any:true, weightsGpu:14540, kv:3277,
  compGpu:812, where:{weightsGpu:["CUDA0","CUDA1"], kv:["CUDA0"], compGpu:["CUDA0"]}})));
var t5m = vramModel("s1", Object.assign({}, z, {any:true, exited:true, oom:true,
  weightsGpu:14540, where:{weightsGpu:["CUDA0"]}}));
var t5 = rj(t5m);
slotBusy = {};
var t6 = rj(vramModel("s1", Object.assign({}, z, {any:true, weightsGpu:14540})));
var ok = /weightsGpu:allocating…[|]kv:queued[|]compGpu:queued/.test(t1)
      && /weightsGpu:14[.]2 GiB>VRAM[|]kv:allocating…/.test(t2)
      && /weightsGpu:14[.]2 GiB>VRAM: CUDA0[+]CUDA1/.test(t4)
      && /kv:3[.]20 GiB>VRAM/.test(t4) && /total:18[.]2 GiB>VRAM/.test(t4)
      && t5m[0].k === "banner" && /kv:failed>OOM/.test(t5) && /compGpu:—/.test(t5)
      && /kv:—/.test(t6) && t6.indexOf("queued") < 0;
process.stdout.write(ok ? "LIFE-OK" : "LIFE-BAD " + t1 + " ## " + t2 + " ## " + t4 + " ## " + t5 + " ## " + t6);
"""
    _r40 = _sp40.run(["node", "-e", "eval(require('fs').readFileSync(0,'utf8'))"],
                     input=_t40.encode(), capture_output=True, timeout=30)
    check(_r40.stdout.decode().strip() == "LIFE-OK",
          "run: the model walks queued behind one allocating..., sizes land "
          "wearing their destination, an OOM death banners and pins the failed "
          "row, and the attempt list persists after the phase ends",
          _r40.stdout.decode()[:200] + _r40.stderr.decode()[:80])
except Exception as _e40x:
    check(False, "the patch40 run did not RUN", str(_e40x)[:140])

