# ---------------------------------------------------------- v3.76 patch77
section("v3.76 patch77: authenticated transport is not a verified file")
# The panel downloads executables and unpacks them into a folder it then runs
# from. It had https, which says WHO sent the bytes, and nothing that said they
# were the bytes that were meant. It also followed a redirect anywhere it was
# pointed, from an address that came out of a remote answer rather than out of
# this file. And with no llama.cpp folder set it read a hard-coded path outside
# the panel's own directory.
# the class existing proves nothing - what matters is that it CHECKS, which a
# textual pin on the class name would happily miss
check(defined(py, "DL_HOSTS") and "def _dl_host_ok(url):" in py
      and "class _DLRedirect(HTTPRedirectHandler):" in py
      and "if not _dl_host_ok(newurl):" in seg(py, "class _DLRedirect",
                                                "_DL_OPENER = build_opener")
      and "refused a redirect to" in py,
      "there is a list of hosts the panel may fetch from, and a redirect off it "
      "is refused")
_dh77 = seg(py, "def _dl_host_ok", "class _DLRedirect")
check('p.scheme == "https"' in _dh77 and 'h in DL_HOSTS' in _dh77 and 'h.endswith(".cdn.hf.co")' in _dh77,
      "https is required, and a host is matched whole - github.com.evil.net is "
      "not github.com; the one suffix allowed is Hugging Face's own CDN namespace, "
      ".cdn.hf.co, with the dot, so cdn.hf.co.evil.example is not it (hotfix3)")
_hg77 = seg(py, "def _hi_get", "def tts_repo_files")
check("if not _dl_host_ok(url):" in _hg77 and "_DL_OPENER.open(" in _hg77,
      "and every fetch goes through both")
_hd77 = seg(py, "def _hi_download", "def _hi_unzip")
check("hashlib.sha256()" in _hd77 and "os.remove(part)" in _hd77
      and "failed its sha256 check and was deleted" in _hd77,
      "what was downloaded is hashed and thrown away if it is not what the "
      "publisher said it would be")
check("def asset_sha(asset):" in py and 'd.startswith("sha256:")' in py,
      "github states a digest per asset, and anything that is not sha256 is "
      "treated as absent rather than guessed at")
check('_hi_download(a["browser_download_url"], zp, name, asset_sha(a))' in py
      and '_hi_download(a["browser_download_url"], zp, what, asset_sha(a))' in py,
      "both engine archives are checked")
check('"sha": str(((it.get("lfs") or {}).get("oid")' in py
      and '_ent.get("sha") or "", n=n)' in seg(py, "def _hi_fetch_listed", "def higgs_install_worker"),   # retold v3.91 patch7: file 1 of the bundle
      # retold v3.97: every file through _hi_fetch_listed, against its listing's oid
      # retold v3.96 patch3: every file of the bundle against its listing's oid, by the one loop
      "and the model, against the oid hugging face states for it")
check('"llamacppPath": ("llama.cpp",),' in py and 'return engine_dir(cfg, "llama", backend) + "\\\\llama-server.exe"' in py,   # retold v3.96 patch2: the folder table
      "with nothing configured, llama.cpp lands inside the panel's own folder")
nin(py, 'or "C:\\\\llama.cpp-cuda"',
    "and the hard-coded path outside it is gone")
_lw77 = seg(py, "def llama_install_worker", "def api_llama_install")
check("dest = tts_fixed_dir(_dk)" in _lw77 and 'st77[_dk] = dest' in _lw77,   # retold v3.96 patch2: per build
      "an install with nowhere to go goes there, and records it")
check("def engine_assets(engine):" in py
      and '"/api/engine-assets": api_engine_assets,' in py,
      "the chooser can ask what an install WOULD fetch")
_cp77 = seg(JS, "function cudaLinePick", "async function llamaInstall")
# retold p82: the digest line is a verdict now, green or red, so its class
# carries the answer with it
check('class="cudafile"' in _cp77 and 'class="cudasha ok">' in _cp77,
      "and shows the file and the digest it will be checked against, before "
      "anything is pressed")
_li77 = seg(JS, "async function llamaInstall", "function renderSetup")
nin(_li77, "uiConfirm",
    "the chooser asked already - a second wall of prose asked it twice")
_pt77 = seg(JS, "const hostItems", "const remoteItems")
check("huggingface.co ONLY" in _pt77 and "sha256 its publisher" in _pt77
      and "inside the PandorumLLM folder" in _pt77,
      "and the permissions tree says all three in the user's own words")
_mv77 = seg(py, "def tts_model_verdict", "# release-0.7 is the floor")
check('"quants": _qs77,' in _mv77 and "tts_quants_desc(_qs77)" in _mv77 and '"repoQuants": tts_repo_quants_cached(pack)}' in _mv77,   # and the repo's, from the cache (patch13)
      "present carries every quantisation of THIS pack that is on disk")
check('"Present: " + ((m.quants || []).length' in JS,
      "and the label lists them instead of repeating the model name that "
      "\"present\" already stood for")
try:
    import hashlib as _hl77
    _urls77 = [(u, fp._dl_host_ok(u)) for u in (
        "https://github.com/a", "https://objects.githubusercontent.com/a",
        "https://huggingface.co/a", "http://github.com/a",
        "https://github.com.evil.net/a", "https://evil.example.com/a")]
    _q77 = fp.tts_quants_desc(["Q4_0", "BF16", "Q8_0", "", "Q8_0"])
    _q78 = fp.tts_quants_desc(["Q4_K", "F32", "IQ4_XS", "Q6_K"])
    _sha77 = [fp.asset_sha(a) for a in ({"digest": "sha256:ABC123"},
                                        {"digest": "md5:xx"}, {})]
    # a digest that does not match must throw the file away, not unpack it
    _body77 = b"x" * 4096
    _good77 = _hl77.sha256(_body77).hexdigest()

    class _R77(io.BytesIO):
        headers = {"Content-Length": str(len(_body77))}
        status = 200

        def __enter__(self):
            return self

        def __exit__(self, *a):
            return False
    _sv77, _svl77 = fp._hi_get, fp._hi_log
    try:
        fp._hi_get = lambda url, headers=None: _R77(_body77)
        fp._hi_log = lambda *a, **k: None      # the gate leaves no trace
        fp.HIGGS_INSTALL.update(cancel=False)
        with _tf50.TemporaryDirectory() as _d77:
            _ok77 = fp._hi_download("https://github.com/a",
                                    os.path.join(_d77, "a.zip"), "t",
                                    "sha256:" + _good77)
            _threw77, _left77 = False, True
            try:
                fp._hi_download("https://github.com/a",
                                os.path.join(_d77, "b.zip"), "t",
                                "sha256:" + "0" * 64)
            except RuntimeError:
                _threw77 = True
                _left77 = os.path.exists(os.path.join(_d77, "b.zip.part"))
    finally:
        fp._hi_get, fp._hi_log = _sv77, _svl77
    check([u for u, ok in _urls77 if ok] == ["https://github.com/a",
                                             "https://objects.githubusercontent.com/a",
                                             "https://huggingface.co/a"]
          and _q77 == ["BF16", "Q8_0", "Q4_0"]
          and _q78 == ["F32", "Q6_K", "IQ4_XS", "Q4_K"]
          and _sha77 == ["abc123", "", ""]
          and os.path.basename(_ok77) == "a.zip"
          and _threw77 and not _left77,
          "run: only https to a listed host is fetched; a good digest passes; a "
          "bad one throws and leaves nothing behind; and quantisations list "
          "biggest first",
          str([[u for u, ok in _urls77 if ok], _q77, _q78, _sha77,
               _threw77, _left77]))
except Exception as _e77x:
    check(False, "the patch77 run did not RUN", str(_e77x)[:140])

# ---------------------------------------------------------- v3.76 patch78
section("v3.76 patch78: a dead end with an address is not a dead end")
# An install that fails leaves the user with nothing to do. The way round it is
# the address it was fetching from - open it, take the file, point the panel at
# the folder - so both failure rows offer it, copyable. Beside that: two
# settings pointed at ONE folder, and the two status headings were given a
# min-width below both their natural widths, which equalises nothing.
_hir78 = seg(JS, "function higgsInstallRow", "const ttsStatDots")
check("You can do it by hand instead" in _hir78
      and 'onclick="copyCode(this)"' in _hir78,
      "a failed TTS install offers the address, and it can be copied")
# retold v3.91 patch5: the engine's address is its own page's row - Settings > Backend Engines > audio.cpp -
# through the same block the TTS row's model failure uses
