# ---------------------------------------------------------- v3.76 patch139
section("v3.76 patch139: the helper clears what it left, and names what it wrote")
# The launcher exe EXITS as soon as it has opened the browser - while the panel
# runs nothing holds it, so it is a file like any other. The rename-aside I had
# built for it was guarding against a case that does not occur, and worse, it
# renamed EVERY file it wrote to .old and never removed them: each update left
# fleet-panel.py.old and friends in the owner's folder.
try:
    _h139 = open(os.path.join(ROOT, "update-helper.py"), encoding="utf-8").read()
    _wr139 = seg(_h139, "# OVERWRITE, and rename aside ONLY if the file is held", "if sha_of(cur) != man[key]:")
    check("except PermissionError:" in _wr139 and 'aside.append(cur + ".old")' in _wr139,
          "a file is overwritten in place; it is renamed aside ONLY if it "
          "genuinely refuses, and what was renamed is remembered")
    nin(seg(_h139, "for key in sorted(man):", "if sha_of(cur) != man[key]:", nth=2)
        if _h139.count("for key in sorted(man):") > 1 else _wr139,
        "if os.path.isfile(cur):\n                    try:\n                        os.replace",
        "and no longer renames every file it writes")
    check('say("wrote %d file(s), %d already current: %s"' in _h139 and '", ".join(written)' in _h139,
          "the files written are NAMED, not counted - the owner asked which two")
    _cl139 = seg(_h139, "# 7. CLEAR THE OLD, now that the new is confirmed answering", 'progress("cleared")')
    check("for p in aside:" in _cl139 and 'nm.lower().endswith(".old")' in _cl139
          and "shutil.rmtree(stage_dir, ignore_errors=True)" in _cl139,
          "with the new panel confirmed, the helper clears what it renamed aside, "
          "any .old an earlier attempt left, and its own staging folder - it is "
          "the right party, having watched the old panel close")
    check("os.chdir(root)" in _cl139,
          "stepping out of the staging folder first - it was started with that "
          "folder as its working directory, and Windows will not remove a "
          "process's current directory, so the rmtree failed silently")
    check('progress("cleared")' in _h139, "and records it as its last step")
    # retold p140: ONE rollback is kept, the latest - older backups roll back to
    # versions that are no longer installed, and they stacked for ever
    check('if nm.startswith("_update-backup-") and nm != keep and os.path.isdir(p):' in _cl139
          and "shutil.rmtree(p, ignore_errors=True)" in _cl139,
          "backups are left alone - they are the rollback")
    check("keep = os.path.basename(backup)" in _cl139,
          "this attempt's backup is the one kept - the only one that rolls the "
          "CURRENT install back")
    _fl139 = seg(_h139, 'say("FAILED: %s" % e)', "return 1")
    nin(_fl139, "_update-backup-",
        "and a failed swap touches no backup at all - it has just restored from "
        "this attempt's, and nothing older is worth deciding about then")
except Exception as _e139a:
    check(False, "the patch139 helper checks did not RUN", str(_e139a)[:140])
check('data-pu="cleared"' in JS and '"Clearing the old files"' in JS,
      "and the dialog has an eighth row for it, marked from that recorded step")
check('has("cleared") || (ph === "back" && V.byVersion) ? "ready"' in JS,
      "a release too old to record steps shows it as left to the next start, "
      "which is where the panel's own tidy runs")
_pt139 = seg(py, "def panel_update_tidy():", "def panel_verify_install():")
check('nm.lower().endswith(".old")' in _pt139 and 'nm.startswith("_panel-update-")' in _pt139
      and "cutoff = time.time() - 3600" in _pt139,
      "the panel's start-time tidy is the fallback: a .old still held when the "
      "helper tried, and staging folders from attempts abandoned before the "
      "helper could tidy its own - an hour old, so an attempt in flight is kept")
nin(_pt139, "_update-backup", "and it, too, leaves the backups alone")
check("panel_update_tidy()" in seg(py, 'with ready_step("install"):', 'with ready_step("tts"):'),
      "run at start, beside the install check")
try:
    _d139 = tempfile.mkdtemp()
    try:
        _rt = os.path.join(_d139, "root")
        os.makedirs(os.path.join(_rt, "logs"))
        _srv = ("import time,socket\ns=socket.socket();s.setsockopt(socket.SOL_SOCKET,"
                "socket.SO_REUSEADDR,1)\ns.bind(('127.0.0.1',%d));s.listen(5)\ntime.sleep(60)\n")
        _sock = socket.socket(); _sock.bind(("127.0.0.1", 0)); _port139 = _sock.getsockname()[1]; _sock.close()
        with open(os.path.join(_rt, "fleet-panel.py"), "w") as _f:
            _f.write(_srv % _port139)
        with open(os.path.join(_rt, "PandorumLLM.exe"), "wb") as _f:
            _f.write(b"OLDEXE")
        with open(os.path.join(_rt, "stale.old"), "w") as _f:
            _f.write("x")
        _stg = os.path.join(_rt, "logs", "_panel-update-t")
        os.makedirs(_stg)
        _hsrc = open(os.path.join(ROOT, "update-helper.py"), "rb").read()
        import zipfile as _zf139
        _zp = os.path.join(_stg, "release.zip")
        with _zf139.ZipFile(_zp, "w") as _z:
            _z.writestr("P/fleet-panel.py", (_srv % _port139).encode())
            _z.writestr("P/PandorumLLM.exe", b"NEWEXE")
            _z.writestr("P/update-helper.py", _hsrc)
        with open(os.path.join(_stg, "update-helper.py"), "wb") as _f:
            _f.write(_hsrc)
        _sha = hashlib.sha256(open(_zp, "rb").read()).hexdigest()
        _p = subprocess.Popen([sys.executable, os.path.join(_rt, "fleet-panel.py")], cwd=_rt)
        threading.Thread(target=_p.wait, daemon=True).start()
        time.sleep(1.0)
        def _kill():
            time.sleep(3.0)
            try:
                _p.kill()
            except Exception:
                pass
        threading.Thread(target=_kill, daemon=True).start()
        _r = subprocess.run([sys.executable, os.path.join(_stg, "update-helper.py"),
                             "--zip", _zp, "--sha", _sha, "--root", _rt,
                             "--port", str(_port139), "--pid", str(_p.pid)],
                            cwd=_stg, capture_output=True, text=True, timeout=150)
        _left = sorted(os.listdir(_rt))
        _logs = sorted(n for n in os.listdir(os.path.join(_rt, "logs")) if not n.startswith("_update-backup"))
        _exe = open(os.path.join(_rt, "PandorumLLM.exe"), "rb").read()
        _res = json.load(open(os.path.join(_rt, "logs", "update-result.json")))
        # the panel the helper started must not outlive the check
        try:
            subprocess.run(["pkill", "-f", os.path.join(_rt, "fleet-panel.py")], timeout=10)
        except Exception:
            pass
    finally:
        shutil.rmtree(_d139, ignore_errors=True)
    check(_exe == b"NEWEXE" and "stale.old" not in _left and "_panel-update-t" not in _logs
          and _res.get("steps", [])[-1:] == ["cleared"] and _res.get("state") == "ok"
          and "PandorumLLM.exe" in (_r.stdout or ""),
          "run: an update that CHANGES the exe overwrites it in place, clears a "
          "stale .old and its own staging folder, names the exe among the files "
          "written, and records cleared as its last step",
          "exe=%r left=%s logs=%s steps=%s" % (_exe[:8], _left, _logs, _res.get("steps"))[:220])
except Exception as _e139x:
    check(False, "the patch139 helper run did not RUN", str(_e139x)[:140])

