section("v3.76 patch141: the error system knows about the features built since it")
# log_error writes the session error file AND the issue record the Log page
# shows. The updater wrote only to update.log; a boot step that failed wrote only
# to panel.log. A failed update or a failed start was invisible in the one place
# a reader looks for what went wrong.
check(defined(py, "UPD_ERR") and '"SHA":       ("UPD-E03",' in py and '"SWAP":      ("UPD-E09",' in py,
      "the updater's failures carry stable codes, in the shape the TTS path's do")
_ue141 = seg(py, "def upd_err(kind, detail=\"\"):", "def update_log(msg):")
check('log_error("update", out)' in _ue141 and "update_log(out)" in _ue141,
      "and a coded failure is written to the session error file and the issue "
      "record as well as update.log")
check(py.count("upd_err(") >= 9, "every refusal the updater can make goes through it")
check('if not msg.startswith("UPD-E"):' in seg(py, "def panel_update_worker():", "def panel_update_apply"),
      "and a failure that arrives without a code - a network error, a full disk - "
      "is given one on the way out, so nothing that stops an update goes unrecorded")
check('log_error("start", "%s failed: %s"' in seg(py, "def ready_step(key, note=", "def ready_state():"),
      "a boot step that throws is an ERROR, not only a line the launch view shows "
      "once")
check("_UPD_VERDICT_SEEN[r.get(\"at\")] = True" in py and 'upd_err("NORETURN" if r.get("stage") == "back" else "SWAP"' in py,
      "the helper's verdict of failure - written while no panel was running - is "
      "recorded by the first panel to serve it, once")
try:
    _d141 = tempfile.mkdtemp()
    _keepF, _keepLog = fp.ERR_FILE[0], list(fp.ERR_LOG)
    _keepS, _keepLD = fp.STACK, fp.log_dir
    try:
        fp.STACK = _d141
        os.makedirs(os.path.join(_d141, "logs"))
        fp.log_dir = lambda *a, **k: os.path.join(_d141, "logs")
        fp.ERR_FILE[0] = None
        del fp.ERR_LOG[:]
        try:
            fp._panel_fetch_verified("u", "")
        except RuntimeError:
            pass
        fp.ready_init()
        try:
            with fp.ready_step("gpus"):
                raise RuntimeError("no card")
        except RuntimeError:
            pass
        with open(os.path.join(_d141, "logs", "update-result.json"), "w") as _fh:
            json.dump({"state": "failed", "stage": "swapping", "reason": "x", "at": time.time()}, _fh)
        fp.api_update_result({})
        fp.api_update_result({})
        _srcs = [e["source"] for e in fp.ERR_LOG]
        _titles = " | ".join(e["title"] for e in fp.ERR_LOG)
    finally:
        fp.ERR_FILE[0] = _keepF
        del fp.ERR_LOG[:]
        fp.ERR_LOG.extend(_keepLog)
        fp.STACK, fp.log_dir = _keepS, _keepLD
        shutil.rmtree(_d141, ignore_errors=True)
    check(_srcs == ["update", "start", "update"] and "UPD-E02" in _titles
          and "UPD-E09" in _titles and "failed: no card" in _titles,
          "run: an updater refusal, a boot step that threw, and a helper verdict "
          "served twice each reach the issue record exactly once, with their codes",
          str(_srcs) + " " + _titles[:120])
except Exception as _e141x:
    check(False, "the patch141 error-record run did not RUN", str(_e141x)[:140])

