# ---------------------------------------------------------- v3.76 patch151
section("v3.76 patch151: a model dropped in is noticed, and a read that fails says why")
# p151 tried to derive this set at import time and reverted: the p12 check above
# already holds the tuple equal to the reader's keys, so the drift a derivation
# would guard against cannot happen, and parsing our own source to prove it is
# the more fragile of the two mechanisms
nin(py, "_scanner_fields", "the completeness set stays a named tuple the gate checks, "
                           "not a runtime parse of our own source")
check("def _models_sig(roots):" in py and '_models_cache.get("sig") == sig' in py
      and "_models_cache.update(t=now, dir=key, items=items, sig=sig, digest=" in py,
      "the folder's own mtime and .gguf count decide whether a scan is needed - the "
      "300s timer is the floor, not the rule")
check("def api_models_rescan(body=None):" in py and 'u.path == "/api/models-rescan"' in py,
      "a door the page can knock on to look again now")
check("def list_models(cfg, quiet=False):" in py and py.count("if not quiet:") == 2
      and "_list_models_once(cfg, quiet=quiet)" in py,
      "and it scans QUIETLY - the boot scan writes per-file progress into the "
      "readiness registry, which is right at boot and wrong for a dropdown")
check("function modelsLookAgain(after, always)" in JS   # retold v3.91 patch3: and after a download, always
      and 'if (wrap.classList.contains("msel")) modelsLookAgain(' in JS
      and 'if (t === "servers" || t === "audio") modelsLookAgain();' in JS,
      "asked when a model menu opens and when the Servers or Audio page is entered (v3.80 patch7)")
check("let modelRescanBusy = false;" in JS and "if (modelRescanBusy) return;" in JS,
      "one at a time")
check("MODEL_SCAN_TRIES = 5" in py and "def _facts_complete(f):" in py
      and 'int(hit.get("_tries", 0)) >= MODEL_SCAN_TRIES' in py,
      "a remembered entry is used only if the read that made it FINISHED, and a file "
      "that keeps failing is left alone after five attempts rather than retried for ever")
check('val["_missing"] = ", ".join(k for k in _KIND_FIELDS if k not in val)' in py
      and "_MODEL_READ_WHY[os.path.abspath(path).lower()]" in py
      and "model scan gave up on %s after %d attempts - missing: %s - %s" in py,
      "and the error names the file, the count, every missing field and the cause in "
      "the reader's own words - not merely that something failed")
try:
    _d151 = tempfile.mkdtemp()
    _keep = (fp._KIND["file"], fp._KIND["map"], fp._TKIND["file"], fp._TKIND["map"],
             fp._model_facts_read_raw, fp.log_error)
    try:
        os.makedirs(os.path.join(_d151, "sub"))
        with open(os.path.join(_d151, "a.gguf"), "wb") as _f:
            _f.write(b"GGUF" + b"\0" * 40)
        _s1 = fp._models_sig([_d151])
        with open(os.path.join(_d151, "sub", "b.gguf"), "wb") as _f:
            _f.write(b"GGUF" + b"\0" * 40)
        _s2 = fp._models_sig([_d151])
        os.remove(os.path.join(_d151, "sub", "b.gguf"))
        _s3 = fp._models_sig([_d151])
        _said151 = []
        fp._KIND["file"] = os.path.join(_d151, "k.json"); fp._KIND["map"] = {"_rules": fp._KIND_RULES}
        fp._TKIND["file"] = os.path.join(_d151, "t.json"); fp._TKIND["map"] = {"_rules": fp._KIND_RULES}
        fp.log_error = lambda *a, **k: _said151.append(a[1] if len(a) > 1 else "")
        fp._model_facts_read_raw = lambda p: (_ for _ in ()).throw(ValueError("header ends after 4 bytes"))
        _reads = [0]
        _orig151 = fp._model_facts_read
        fp._model_facts_read = lambda p: (_reads.__setitem__(0, _reads[0] + 1), _orig151(p))[1]
        for _ in range(8):
            fp.model_facts(os.path.join(_d151, "a.gguf"))
        fp._model_facts_read = _orig151
        _fail = fp.model_scan_failures()
    finally:
        (fp._KIND["file"], fp._KIND["map"], fp._TKIND["file"], fp._TKIND["map"],
         fp._model_facts_read_raw, fp.log_error) = _keep
        shutil.rmtree(_d151, ignore_errors=True)
    check(_s1 != _s2 and _s3 == _s1,
          "run: a model added changes the folder fingerprint, and removing it changes "
          "it back - which is how a file dropped in is noticed at once")
    check(_reads[0] == 5 and len(_said151) == 1 and "header ends after 4 bytes" in _said151[0]
          and len(_fail) == 1 and _fail[0]["tries"] == 5 and "arch" in _fail[0]["missing"],
          "run: eight asks make five read attempts and one error, naming the cause; "
          "the ledger holds the file, the count and what was missing",
          "%r %r" % (_reads[0], _said151[:1]))
except Exception as _e151x:
    check(False, "the patch151 runs did not RUN", str(_e151x)[:140])

