check("const repos = [];" in _ag152 and 'hgCode("https://huggingface.co/" + r)' in _ag152,
      "the repo the models come from is named at the top, taken from the packs "
      "themselves rather than written out a second time")
check("const dest = mroot + BS + (p.dir || p.fam);" in _ag152 and "st.ttsAcppModelsDir ||" in _ag152,
      "and every download line names the models folder AS SET - an install on "
      "another drive gets its own path, not C:")
try:
    if JSDOM_CWD is None:
        raise RuntimeError("jsdom is not installed and could not be fetched - this run is skipped")
    _sf152 = os.path.join(tempfile.mkdtemp(), "tts.js")
    # retold v3.95: the guide and the two helpers it draws with, nothing else
    _a152 = JS.index("function hgStep(")
    _b152 = JS.index("\nlet ttsModels = null;", JS.index("function renderTtsGuide()"))
    with open(_sf152, "w", encoding="utf-8", errors="surrogatepass") as _f:
        _f.write(JS[_a152:_b152])
    _drv152 = """
const {JSDOM} = require(%r); const fs = require("fs");
const dom = new JSDOM('<body><div id="ugpane-tts"></div></body>', {runScripts: "outside-only"});
const w = dom.window;
const D = String.fromCharCode(69) + ':';
const pre = 'var esc=function(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;");}; var $=function(id){return window.document.getElementById(id);}; var ICO={copy:"c"}; var hgStep=function(n,t,b){return "<div class=hgs><b>"+n+". "+t+"</b>"+b+"</div>";};'
  + 'var state={acppMin:"0.7",settings:{ttsAcppDir:"' + D + '\\\\G\\\\PandorumLLM\\\\audio.cpp",ttsAcppModelsDir:"' + D + '\\\\G\\\\PandorumLLM\\\\Models\\\\TTS",ttsWrapperPort:7860},ttsPacks:[{fam:"higgs_audio_tts",label:"Higgs TTS 3",gb:"5.1 GB",task:"tts",repo:"audio-cpp/audio.cpp-gguf",path:"H/x.gguf",dir:"Higgs-v3-4b",licence:"l"}]};';
w.eval(pre + fs.readFileSync(%r, "utf8") + "; renderTtsGuide();");
const p = w.document.getElementById("ugpane-tts"), txt = p.textContent;
const codes = [...p.querySelectorAll(".gcode, code")].map(c => c.textContent);
const repo = codes.some(c => c.indexOf("huggingface.co/audio-cpp/audio.cpp-gguf") >= 0);
const dest = codes.some(c => c.indexOf("hf download") >= 0 && c.indexOf(D) >= 0 && c.indexOf("Models") >= 0);
const noC = txt.indexOf(String.fromCharCode(67) + ":") < 0;
process.stdout.write([repo, dest, noC].join("|"));
"""
    _r152 = _sp40.run(["node", "-e", _drv152 % (os.path.join(JSDOM_CWD, "node_modules", "jsdom"), _sf152)],
                      capture_output=True, timeout=60, cwd=JSDOM_CWD)
    check(_r152.stdout.decode().strip() == "true|true|true",
          "run: an install on E: gets the repo link at the top, download lines naming "
          "ITS models folder, and no C: path anywhere in the guide",
          _r152.stdout.decode()[:100] + _r152.stderr.decode()[:160])
except Exception as _e152x:
    check(False, "the patch152 guide run did not RUN", str(_e152x)[:140])

