section("v3.76 patch157: the server cannot answer that, and two saves cannot share a name")
_sp157 = seg(py, 'caps = js.get("chat_template_caps")', '"keepsReasoning"')
check('"thinks": (bool(caps.get("supports_thinking"))' in _sp157
      and 'if "supports_thinking" in caps else None)' in _sp157,
      "ONLY a build that publishes supports_thinking has answered - "
      "common_chat_templates_support_enable_thinking decides a request's switch and "
      "is printed as a trace line, never serialised into /props")
# the two other caps ARE read - keepsReasoning is a real field the page shows -
# but neither may decide the THINKING verdict, which is the thing p155 got wrong
_th157 = seg(py, '"thinks": (bool(caps.get("supports_thinking"))', '"keepsReasoning"')
for _cap157 in ("supports_reasoning_effort", "supports_preserve_reasoning"):
    nin(_th157, _cap157,
        "and the reasoning-effort and preserve-reasoning caps are NOT consulted for "
        "the thinking verdict: they answer different questions - levels, and keeping "
        "reasoning in history - and a template can carry an enable_thinking switch "
        "without either, which is why the card went back to 'no switch' the moment a "
        "server started (p155's fault)")
check("_SAVE_SEQ = itertools.count(1)" in py
      and '"%s.%d.%d.tmp" % (_dst, os.getpid(), next(_SAVE_SEQ))' in py and "_dst = path or CONFIG" in py,
      "the config's scratch file is named per CALL, not per process - two saves at "
      "once wrote one path, the first rename consumed it, and the second answered "
      "WinError 2 with the reader's settings lost")
nin(py, "_SAVE_LOCK",
    "and NO lock guards the save: panel_log reaches log_dir, which reaches "
    "load_config, which can save - so a save holding a lock waits on itself, which "
    "is what the p123 probe caught when this patch first tried it")
try:
    _d157 = tempfile.mkdtemp()
    _c157 = fp.CONFIG
    try:
        fp.CONFIG = os.path.join(_d157, "fleet-config.json")
        _errs157 = []
        def _hammer157(i):
            for _ in range(25):
                try:
                    fp.save_config({"n": i})
                except Exception as e:
                    _errs157.append("%s: %s" % (type(e).__name__, e))
        _ts157 = [threading.Thread(target=_hammer157, args=(i,)) for i in range(8)]
        for _t in _ts157:
            _t.start()
        for _t in _ts157:
            _t.join()
        _ok157 = isinstance(json.load(open(fp.CONFIG, encoding="utf-8")), dict)
        _stray157 = [f for f in os.listdir(_d157) if f.endswith(".tmp")]
    finally:
        fp.CONFIG = _c157
        shutil.rmtree(_d157, ignore_errors=True)
    check(not _errs157 and _ok157 and not _stray157,
          "run: 200 saves from eight threads at once, none refused, the config still "
          "reads as JSON and no scratch file is left behind",
          "%r %r %r" % (_errs157[:2], _ok157, _stray157))
except Exception as _e157x:
    check(False, "the patch157 save run did not RUN", str(_e157x)[:140])

