section("v3.76 patch158: order is taken at the door, and the panel says what it was asked")
check("ARRIVAL_SEQ = itertools.count(1)" in py and "def process_request(self, request, client_address):" in py
      and "self._pending_arrival = (next(ARRIVAL_SEQ), time.time())" in py,
      "the sequence is taken in process_request - the last point at which FIFO is "
      "still true. _QuietServer threads each request, and from that moment the panel "
      "held no record of which chunk arrived first")
check("def process_request_thread(self, request, client_address):" in py
      and "ARRIVAL[threading.get_ident()] = got" in py
      and "engine_release(_gone[0])" in py,
      "and the handling thread carries it, releasing the place however the request "
      "ends - one that never speaks must not stall the queue")
check("def engine_expect(seq):" in py and "engine_expect(_seq)" in py
      and "min(ENGINE_EXPECT) != self.seq" in py,
      "the place is reserved BEFORE prep: ordering only those already queued let a "
      "chunk with 5ms of prep take the turn ahead of a sibling with 970ms, which is "
      "the same race one step later")
check("class engine_turn(object):" in py and "with engine_turn(_qseq):" in py
      and "ENGINE_QUEUE_MAX_S = 90.0" in py,
      "one chunk holds audio.cpp at a time, with a cap so a turn nobody releases "
      "cannot stop the panel")
check("if self.seq is None:" in seg(py, "class engine_turn(object):", "def tts_acpp_speak"),
      "and a call the panel starts itself - the primer, a calibration run - is served "
      "as it comes rather than made to wait behind SkyrimNet's queue")
check("_t_post = time.monotonic()" in seg(py, "with engine_turn(_qseq):", "if str(st.get(\"ttsRunawayMode\")")
      and "waited %.2fs for the engine" in py,
      "the clock starts INSIDE the turn, so server ms is synthesis rather than "
      "synthesis plus somebody else's turn - the number that feeds the cps "
      "calibration, the chunk cap and the thought timer")
check("def tts_arrival_note(seq, data, peer=None" in py
      and 'TTS_ORIGINS = ("sn-tts", "panel-auto", "page-click", "panel-prime", "panel-cal")' in py,
      "every speech request writes a line the moment it ENTERS, naming who asked - "
      "the panel could say what it finished and never what it was asked")
check('tts_arrival_note(_seq, data, self.client_address,' in py
      and 'origin="panel-auto"' in py and 'origin="page-click"' in py,
      "at all of its doors: SkyrimNet's, the thought timer's, and the page's replay")
try:
    _said158 = []
    _lg158 = fp.TTSW.log
    try:
        fp.TTSW.log = lambda m: _said158.append(m)
        fp.tts_arrival_note(41, ["a spoken chunk"], ("127.0.0.1", 51122), origin="sn-tts")
        fp.tts_arrival_note(None, ["a thought"], None, origin="panel-auto", note="thought for Ann")
        fp.tts_arrival_note(43, [], ("127.0.0.1", 51125), origin="sn-tts", note="no data")
    finally:
        fp.TTSW.log = _lg158
    check(len(_said158) == 3 and "arrival #41" in _said158[0] and "sn-tts" in _said158[0]
          and "panel-auto" in _said158[1] and "(no text)" in _said158[2],
          "run: a chunk, a panel-started thought and a request carrying nothing each "
          "leave a line naming their origin", repr(_said158)[:200])
    _order158 = []
    def _chunk158(seq, prep):
        fp.engine_expect(seq)
        time.sleep(prep)
        with fp.engine_turn(seq):
            _order158.append(seq)
            time.sleep(0.03)
    _ts158 = [threading.Thread(target=_chunk158, args=a) for a in ((1, 0.30), (2, 0.02), (3, 0.05))]
    for _t in _ts158:
        _t.start()
    for _t in _ts158:
        _t.join()
    _skip158 = []
    def _maybe158(seq, prep, speaks):
        fp.engine_expect(seq)
        time.sleep(prep)
        if speaks:
            with fp.engine_turn(seq):
                _skip158.append(seq)
        else:
            fp.engine_release(seq)
    _ts2 = [threading.Thread(target=_maybe158, args=a) for a in ((11, 0.05, False), (12, 0.02, True), (13, 0.03, True))]
    for _t in _ts2:
        _t.start()
    for _t in _ts2:
        _t.join()
    check(_order158 == [1, 2, 3] and _skip158 == [12, 13],
          "run: 970ms of prep on the first chunk and 20ms on the second - arrival "
          "order still holds; and a request that never speaks does not hold the rest up",
          "%r %r" % (_order158, _skip158))
except Exception as _e158x:
    check(False, "the patch158 queue run did not RUN", str(_e158x)[:140])

