# ---------------------------------------------------------- v3.76 patch173
section("v3.76 patch173: ask the unified source FIRST")
# THE STANDING RULE, GATED. Anything that shows an element the tables name -
# a terminal, the payload card, anything that grows beside them - takes its ink
# and its weight from PAINT and ELEM, never from a literal at the site. This is
# what the owner asked for after the provider weight: it had been DECLARED at
# p172 and one painter simply did not ask, so four terminals went bold and the
# Proxy terminal did not. A surface that carries its own colour is a surface
# that will be left behind by the next change.
for _who173, _a173, _b173 in (
        ("paintTok", "function paintTok(tk, inPay, plain)", "return tint25(SD.text, tk);"),
        ("drawSegs", "function drawSegs(segs, pane)", "function refName(term, kind, id)"),
        ("paintSpoken", "function paintSpoken(line, pane)", "function hasRecord(line, title)"),
        ("the payload header", "const chip = (txt, col)", "const body =")):
    _s173 = seg(JS, _a173, _b173)
    nin(_s173, "color:#",
        "%s carries no colour of its own - it asks the table" % _who173)
    check(bool(re.search(r"ELEM\.\w+\.|PAINT\.\w+|SP\[|SD\.\w+|inkOf\(|entInk\(",
                         _s173)),
          "and %s READS the table rather than merely avoiding a literal" % _who173)
check('out["lastOffset"] = _off' in py or "_off > out[\"lastOffset\"]" in py,
      "the tensor table's largest offset is KEPT - the reader was reading the field "
      "and throwing it away")
check('out["dataStart"] = ((_here + 31) // 32) * 32' in py
      and "_need = int(scan.get(\"dataStart\") or 0) + int(scan.get(\"lastOffset\") or 0)" in py
      and "if _need and _have + 32 < _need:" in py
      and "still being copied in?" in py,
      "THE FILE SAYS HOW BIG IT HAS TO BE. A model half-copied in reads as a model: "
      "the header and the table live at the FRONT, so they land first and parse "
      "cleanly while the weights are on their way. No timer answers that honestly - "
      "waiting longer is a guess about someone else's disk. A file shorter than its "
      "own table demands is not all here, and one short by less than an alignment "
      "unit is short by PADDING, not by a copy")
try:
    _d173 = tempfile.mkdtemp()
    def _kv173(k, v):
        return (struct.pack("<Q", len(k)) + k.encode() + struct.pack("<I", 8)
                + struct.pack("<Q", len(v)) + v.encode())
    _body173 = (b"GGUF" + struct.pack("<I", 3) + struct.pack("<Q", 1)
                + struct.pack("<Q", 1) + _kv173("general.architecture", "llama"))
    _nm173 = b"blk.0.attn_q.weight"
    _body173 += (struct.pack("<Q", len(_nm173)) + _nm173 + struct.pack("<I", 1)
                 + struct.pack("<Q", 4096) + struct.pack("<I", 0)
                 + struct.pack("<Q", 1 << 30))
    _whole173 = os.path.join(_d173, "whole.gguf")
    _part173 = os.path.join(_d173, "part.gguf")
    for _p in (_whole173, _part173):
        with open(_p, "wb") as _f:
            _f.write(_body173 + b"\x00" * 64)
    with open(_whole173, "r+b") as _f:
        _f.truncate((1 << 30) + 8192)
    _read173 = []
    for _p in (_whole173, _part173):
        try:
            fp._model_facts_read(_p)
            _read173.append("read")
        except Exception as _e:
            _read173.append("refused" if "still being copied in" in str(_e) else "other")
    shutil.rmtree(_d173, ignore_errors=True)
    check(_read173 == ["read", "refused"],
          "run: a whole GGUF is read and a half-copied one is REFUSED by name, with "
          "no timer and nothing to wait for", repr(_read173))
except Exception as _e173x:
    check(False, "the patch173 copy-in-progress run did not RUN", str(_e173x)[:140])
check("ELEM.prov.bold" in JS and "st && st.bold" in JS,
      "the provider's weight is DECLARED once and honoured by both painters - it was "
      "declared at p172 and only drawSegs asked, so the Proxy terminal stayed light "
      "while the other four went bold")
check("'<span class=\"payfield\" style=\"color:' + PAINT.dim" in JS
      and "'<span style=\"color:' + PAINT.think" in JS,
      "the payload card shows what the terminals show, so it reads what they read - "
      "it carried its own dim grey and its own reasoning grape, and a change to "
      "either would have moved five terminals and left this card behind")

