# ---------------------------------------------------------- v3.80 patch25
# A song made from a song. ACE-Step 1.5 takes a recording two ways and its own
# GenerationParams name them: src_audio for a cover, reference_audio for a style
# reference, audio_cover_strength and task_type beside them. Every documented
# spelling goes and the engine's refusals keep the one it reads, as with the
# duration. The other families are generation only.
section("v3.80 patch25: a song made from a song - cover and style reference for ACE-Step")

try:
    _c25 = {"settings": dict(fp.DEF_SETTINGS)}
    _c25["settings"]["songFamily"] = "ace_step"
    _base25 = {"caption": "jazz piano version", "lyrics": "[Verse]" + chr(10) + "x", "seconds": ""}
    _cov25 = flat47(fp.song_request_body(dict(_base25, srcaudio="C:/m/original.wav", strength="0.8"), _c25)["request"])
    _sty25 = flat47(fp.song_request_body(dict(_base25, refaudio="C:/m/sound.wav", strength="0.2"), _c25)["request"])
    _non25 = flat47(fp.song_request_body(dict(_base25), _c25)["request"])
    _c25["settings"]["songFamily"] = "minimax_music3"
    _mm25 = flat47(fp.song_request_body(dict(_base25, srcaudio="C:/m/original.wav", refaudio="C:/m/s.wav", strength="0.5"), _c25)["request"])
    _keepU25 = dict(fp.ACPP_UNWANTED)
    fp.ACPP_UNWANTED["song:ace_step"] = {"src_audio_path", "source_audio", "cover_strength"}
    _c25["settings"]["songFamily"] = "ace_step"
    _aft25 = flat47(fp.song_request_body(dict(_base25, srcaudio="C:/m/original.wav", strength="0.8"), _c25)["request"])
    fp.ACPP_UNWANTED.clear(); fp.ACPP_UNWANTED.update(_keepU25)
    # the spellings are NAMED here, not read from the table under test - a check that iterates the
    # table only checks what the table kept (a one-name table passed that way) (patch25)
    check(all(_cov25.get(_n) == "C:/m/original.wav" for _n in ("src_audio", "src_audio_path", "source_audio"))
          and _cov25.get("audio_cover_strength") == 0.8 and _cov25.get("task_type") == "cover"
          and "reference_audio" not in _cov25
          and all(_sty25.get(_n) == "C:/m/sound.wav" for _n in ("reference_audio", "reference_audio_path", "ref_audio"))
          and _cov25.get("cover_strength") == 0.8
          and _sty25.get("task_type") == "text2music" and "src_audio" not in _sty25
          and not any(_k in _non25 for _k in ("src_audio", "reference_audio", "task_type", "audio_cover_strength"))
          and not any(_k in _mm25 for _k in ("src_audio", "reference_audio", "task_type", "audio_cover_strength"))
          and _aft25 == {"text": "jazz piano version", "lyrics": "[Verse]" + chr(10) + "x", "duration_seconds": -1,
                         "src_audio": "C:/m/original.wav", "audio_cover_strength": 0.8, "task_type": "cover"},
          "run: a cover sends the recording as src_audio under every documented spelling with its strength and "
          "task_type cover; a style reference sends reference_audio and stays text2music; neither one sent leaves "
          "the request exactly as it was; the families that only generate never see the fields; and once the "
          "engine has refused the spellings it does not know, only the ones it reads are sent",
          str((_cov25, _aft25))[:260])
except Exception as _e25:
    check(False, "the patch25 audio-in run did not RUN", str(_e25)[:140])
check(fp.SONG_AUDIO_IN == {"ace_step": {"src": ("src_audio", "src_audio_path", "source_audio"),
                                         "ref": ("reference_audio", "reference_audio_path", "ref_audio"),
                                         "strength": ("audio_cover_strength", "cover_strength"),
                                         "task": ("task_type",)}}
      and fp.SONG_FIELD_TYPES.get("strength") is float,
      "the names are ACE-Step's own (src_audio, reference_audio, audio_cover_strength, task_type) and only the "
      "family audio.cpp lists for music EDITING has them")
check("function songAudioInRow()" in JS and 'fam === "ace_step" ? songAudioInRow() : ""' in JS
      and 'id="song-srcaudio"' in JS and 'id="song-refaudio"' in JS and 'id="song-strength"' in JS
      and '"srcaudio", "refaudio", "strength", "voice"]' in JS and '"srcaudio", "refaudio", "strength",' in py,   # the Voice rides with them (patch40)
      "the Song Creator offers the recording and its strength to ACE-Step alone, and the three travel with the ask")

# ---------------------------------------------------------- v3.80 patch26
# The owner's p25 report. Exit stopped the TTS server and left the song server
# running; the next panel then showed it serving and could not stop it, because a
# panel stopped only what it had started - three Terminates passed it by. Stop,
# Terminate and Exit now reach a leftover on the song port, and only a process
# named audiocpp_server. The running gear is a real gear, larger, turning in place.
section("v3.80 patch26: a song server left behind can be stopped; Exit stops it; a real gear, turning in place")

try:
    _calls26 = []
    _keep26 = (fp._kill_port_owner, fp.panel_log, fp.song_log, fp.load_config, fp.slot_status, dict(fp.SONG_PROC))
    fp._kill_port_owner = lambda port, only="": _calls26.append((port, only))
    fp.panel_log = lambda m: None; fp.song_log = lambda m: None
    fp.load_config = lambda *a, **k: {"settings": dict(fp.DEF_SETTINGS)}
    fp.SONG_PROC.update(pid=None, proc=None)
    fp.slot_status = lambda p: {"state": "serving"}
    _left26 = fp.song_kill_leftover("terminate button")
    _got26 = list(_calls26)
    fp.slot_status = lambda p: {"state": "down"}
    _none26 = fp.song_kill_leftover("x")
    fp.SONG_PROC.update(pid=7)
    fp.slot_status = lambda p: {"state": "serving"}
    _ours26 = fp.song_kill_leftover("x")
    check(_left26 is True and _got26 == [(fp.song_server_port(), "audiocpp_server")]
          and _none26 is False and _ours26 is False and len(_calls26) == 1,
          "run: a song server this run did not start - one a previous run left - is stopped by its port, and ONLY "
          "a process named audiocpp_server; an empty port is left alone; the panel's own server goes through the "
          "normal stop. The owner's was left at Exit and three Terminates passed it by",
          str((_left26, _got26, _none26, _ours26))[:200])
finally:
    try:
        fp._kill_port_owner, fp.panel_log, fp.song_log, fp.load_config, fp.slot_status = _keep26[:5]
        fp.SONG_PROC.clear(); fp.SONG_PROC.update(_keep26[5])
    except NameError:
        pass
_ex26 = seg(py, "def full_exit(reason, kill_servers=True):", "out = run_fleet([\"-Stop\"])")
check("stop_song_server(reason)" in _ex26 and "song_kill_leftover(reason)" in _ex26
      and 'song_kill_leftover("terminate button")' in seg(py, "def api_terminate(body):", "def api_exit(body):")
      and 'song_kill_leftover("stop button")' in seg(py, "def api_song_server(body):", 'if action == "start":'),
      "Exit, Terminate and the song server's own Stop all reach a leftover - Exit stopped the TTS server and "
      "never the song server")
check("def _kill_port_owner(port, only=\"\"):" in py and "$p.ProcessName -eq" in py
      and "else \"Stop-Process -Id $c.OwningProcess -Force\"" in py,
      "the port killer can be told whose process it may stop; without a name it keeps its old behaviour for the "
      "ports that are the panel's alone")
check("transform-origin:50% 50%;" in seg(py, "  .lcluster .lrow button.go.lbrun::after {\r\n", "@keyframes lgearSpin")   # the rule itself, not its mention in the reduced-motion line
      and "width:16px; height:16px; margin-left:-8px;" in py and "background-size:16px 16px;" in py
      and all(("#%s.lbrun::after { background-image:url(" % _b) in py for _b in ("launchBtn", "launchTtsBtn", "launchSongBtn"))
      and py.count("fill-rule%3D%22evenodd%22") == 3,
      "the running gear is a real gear - eight teeth, a body and a hub hole - at 16px, turning about its own "
      "centre so it spins in place")

# ---------------------------------------------------------- v3.80 patch27
# The owner's TTS report. Scripted Skyrim dialogue arrives as PTI records a
# second or two apart, each naming its own line; patch24 rightly keeps each line
# under its record, which drew one box per line - consecutive PTI records within
# a few seconds now share one bracket. A voiced thought keeps its realtime figure
# with Dialogue Text off. And a switch the owner asked for: Force player thought
# voice - SkyrimNet voices the player's thoughts itself or not at all; on, the
# panel voices them in the player's own sample.
section("v3.80 patch27: quick PTI records share a bracket; thoughts keep their speed; force player thought voice")

try:
    _dv27 = tempfile.mkdtemp()
    _jsf27 = os.path.join(_dv27, "page.js")
    with open(_jsf27, "w", encoding="utf-8", errors="surrogatepass") as _f:
        _f.write(JS)
    _M27 = chr(0x25C8)
    def _pti27(stamp, pid):
        return "[%s] %s PTI             [1237]     630 /    14          tok  14120 / 249 tps     0.290 sec  %s%d%s" % (stamp, _M27, chr(0x27E6), pid, chr(0x27E7))
    def _rec27(stamp, title, pid):
        return "[%s] %s %-15s [1236]    8994 /    56          tok   2882 /  79 tps     3.870 sec  %s%d%s" % (stamp, "*", title, chr(0x27E6), pid, chr(0x27E7))
    _dash27 = chr(10).join([
        _pti27("14:13:34.85", 1), _pti27("14:13:36.33", 2),            # 1.5 s: one bracket
        _pti27("14:18:54.13", 3), _rec27("14:18:54.74", "Dialogue", 4),  # an NPC reply between...
        _pti27("14:18:58.71", 5),                                        # ...so this stays apart
        _pti27("14:27:40.21", 6), _pti27("14:27:55.00", 7),              # 14.8 s: too far apart (11 s since patch29)
    ])
    _W27 = chr(12336) + chr(65039)
    _th27 = chr(10).join(["[15:07:30.22] Combat          [1236]    8994 /    56          tok   2882 /  79 tps     3.870 sec",
                          "[15:07:30.23]    " + chr(0x251C) + chr(0x2500) + " " + chr(0x1F4AD) + " Death Hound: " + _W27 + " The wizard is fast, but I can flank those ghosts. " + _W27])
    _tail27 = chr(10).join(["[15:07:32.80] " + chr(0x1F4AD) + " Death Hound (thought): " + chr(12336) + " The wizard is fast, but I can flank those ghosts. " + chr(12336),
                            "", "[15:07:32.80] " + chr(0x26A1) + " 3.37x realtime (1.27s " + chr(0x2192) + " 4.3s audio)"])
    _drv27 = """
const sb = require(%r);
const L = sb.load(%r, ["bundlePlayer", "segGroups", "dropSpokenRows", "annotateThoughts"], "  globalThis.__setTts = function (t) { lastTtsTail = t; };");
const out = {};
const t = L.F.bundlePlayer(%s);
const ls = t.split(String.fromCharCode(10));
out.boxes = L.F.segGroups(ls, "dashboard").map(g => g.map(i => { const s = ls[i]; const a = s.indexOf(String.fromCodePoint(0x27E6)), b = s.indexOf(String.fromCodePoint(0x27E7)); return (a >= 0 && b > a) ? s.slice(a + 1, b) : "?"; }));
L.ctx.__setTts(%s);
const off = L.F.annotateThoughts(L.F.dropSpokenRows(%s));
out.offBolt = off.indexOf("3.37x") >= 0;
process.stdout.write(JSON.stringify(out));
""" % (os.path.join(ROOT, "gate-tools", "page-sandbox.js"), _jsf27, json.dumps(_dash27), json.dumps(_tail27), json.dumps(_th27))
    _f27 = os.path.join(_dv27, "d.js")
    with open(_f27, "w", encoding="utf-8", errors="surrogatepass") as _f:
        _f.write(_drv27)
    _r27 = subprocess.run(["node", _f27], capture_output=True, timeout=120)
    try:
        _o27 = json.loads(_r27.stdout.decode("utf-8", "replace") or "{}")
    except Exception:
        _o27 = {}
    check(_o27.get("boxes") == [["1", "2"], ["3"], ["4"], ["5"], ["6"], ["7"]],
          "run: PTI records 1.5 s apart with nothing between them share ONE bracket - SkyrimNet makes a PTI call "
          "per player line, so scripted dialogue drew one box per line after patch24; a PTI record with an NPC "
          "reply before it stays apart, and so do two more than six seconds apart",
          str(_o27)[:200] + _r27.stderr.decode()[:100])
    # the run proves the two functions together; the pin proves the Off branch is what composes them -
    # a run that calls them directly passed with the branch reverted (patch27's own control)
    check(_o27.get("offBolt") is True
          and "text = annotateThoughts(dropSpokenRows(text));" in seg(JS, "else if (TERM_INS_KINDS.indexOf(which) >= 0) {", "if (ttsHeldBack())"),
          "run: with Dialogue Text off a VOICED thought keeps its realtime figure - the annotation ran only inside "
          "the splice, so the Off branch dropped it")
except Exception as _e27:
    check(False, "the patch27 page run did not RUN", str(_e27)[:140])
try:
    _keep27 = (fp.tts_thought_say, fp.threading.Thread, fp._spk_player[0])
    _said27 = []
    fp.tts_thought_say = lambda who, text, origin="x": _said27.append((who, text, origin))
    class _T27(object):
        def __init__(self, target=None, args=(), daemon=None):
            self.t, self.a = target, args
        def start(self):
            self.t(*self.a)
    fp.threading.Thread = _T27
    fp._spk_player[0] = "Maxxor"
    _s27 = "<internal_thought>Still more in the shadows. I must keep my guard up.</internal_thought>"
    def _run27(force, who):
        del _said27[:]
        _c = {"settings": dict(fp.DEF_SETTINGS)}
        _c["settings"]["ttsPlayerThoughtForce"] = force
        _c["settings"]["ttsThoughtOut"] = "off"
        fp.thought_lines(_s27, who, _c)
        return list(_said27)
    _on_p = _run27("on", "Maxxor"); _on_n = _run27("on", "Dagur"); _off_p = _run27("off", "Maxxor")
    check(_on_p == [("Maxxor", "Still more in the shadows. I must keep my guard up.", "panel-force")]
          and _on_n == [] and _off_p == [] and fp.DEF_SETTINGS.get("ttsPlayerThoughtForce") == "off"
          and fp.tts_is_player_name("maxxor") and not fp.tts_is_player_name("Dagur"),
          "run: with Force player thought voice on, the player's thought is voiced by the panel in the player's "
          "own sample; an NPC's is left to its own route; off - the default - the panel voices only what "
          "SkyrimNet asks for",
          str((_on_p, _on_n, _off_p))[:200])
finally:
    try:
        fp.tts_thought_say, fp.threading.Thread, fp._spk_player[0] = _keep27
    except NameError:
        pass
check('id="tts-ttsPlayerThoughtForce" onchange="saveTts()"' in JS and "Force player thought voice" in JS
      and 'body.ttsPlayerThoughtForce = e.checked ? "on" : "off";' in JS
      and before(JS, 'id="tts-ttsThoughtAudio"', 'id="tts-ttsPlayerThoughtForce"'),
      "the switch sits under the NPC thought selector and saves by its checked state, not its value")

# ---------------------------------------------------------- v3.80 patch28
# The owner's p27 report. The three launch buttons were built by three rules:
# Terminate marked the TTS server as stopping by hand and never the song server,
# and only the SG button held its red pulse for a beat. One shared stop rule now,
# and Terminate marks the song server as it marks the TTS one. The remote page:
# a browser refuses sound until a page has been clicked once, and the page
# swallowed that refusal - now it says so, a first click unlocks sound for the
# page's life, and a Web Lock keeps a minimized tab from being frozen.
section("v3.80 patch28: one stop rule for the three buttons; Terminate marks the song server; sound in a minimized page")

try:
    _dv28 = tempfile.mkdtemp()
    _jsf28 = os.path.join(_dv28, "page.js")
    with open(_jsf28, "w", encoding="utf-8", errors="surrogatepass") as _f:
        _f.write(JS)
    _drv28 = """
const sb = require(%r);
const L = sb.load(%r, ["syncSongButton", "syncTtsButton", "LB_TERM", "state", "soundRefused", "soundUnlock"],
  "  state = { settings: {}, songServer: { pid: 5, state: 'serving' }, ttsServer: { state: 'serving' } }; window = globalThis;"
  + " setInterval = function(){return 1;}; clearInterval = function(){}; setTimeout = function(){ return 1; }; clearTimeout = function(){};"
  + " globalThis.__set = function (k, v) { if (k === 'songBusy') songBusy = v; if (k === 'ttsBusy') ttsBusy = v; };"
  + " globalThis.__warns = []; sendClientWarn = function (w) { globalThis.__warns.push(w.msg); };"
  + " const mk = () => ({ innerHTML: '', isConnected: true, classList: { list: [], add(...a){ for (const x of a) if (!this.list.includes(x)) this.list.push(x); }, remove(...a){ this.list = this.list.filter(x => !a.includes(x)); }, contains(x){ return this.list.includes(x); }, toggle(x, v){ v ? this.add(x) : this.remove(x); } } });"
  + " globalThis.__sg = mk(); globalThis.__tts = mk(); globalThis.__bar = null;"
  + " document.body = { insertAdjacentHTML(w, h) { globalThis.__bar = { html: h, remove() { globalThis.__bar = null; } }; } };"
  + " document.getElementById = function (id) { return id === 'launchSongBtn' ? globalThis.__sg : id === 'launchTtsBtn' ? globalThis.__tts : id === 'soundbar' ? globalThis.__bar : null; };");
const S = L.ctx.__probe_state || L.F.state;
const cls = b => b.classList.list.slice().sort().join("+") || "dormant";
const out = {};
L.F.syncSongButton(); L.F.syncTtsButton(); out.running = [cls(L.ctx.__sg), cls(L.ctx.__tts)];
L.ctx.__set("songBusy", "stop"); L.ctx.__set("ttsBusy", "stop");
L.F.syncSongButton(); L.F.syncTtsButton(); out.stopping = [cls(L.ctx.__sg), cls(L.ctx.__tts)];
S.songServer = {}; S.ttsServer = {}; L.ctx.__set("ttsBusy", "");
L.F.syncSongButton(); L.F.syncTtsButton(); out.nextPoll = [cls(L.ctx.__sg), cls(L.ctx.__tts)];
L.F.LB_TERM.sg.at = 0; L.F.LB_TERM.tts.at = 0;
L.F.syncSongButton(); L.F.syncTtsButton(); out.afterBeat = [cls(L.ctx.__sg), cls(L.ctx.__tts)];
out.refusedSays = L.F.soundRefused({ name: "NotAllowedError" }, "a spoken line") && !!L.ctx.__bar && L.ctx.__warns.length === 1;
L.F.soundRefused({ name: "NotAllowedError" }, "another line"); out.saidOnce = L.ctx.__warns.length === 1;
out.otherError = L.F.soundRefused({ name: "AbortError" }, "x") === false;
L.F.soundUnlock(); out.clickClears = L.ctx.__bar === null;
process.stdout.write(JSON.stringify(out));
""" % (os.path.join(ROOT, "gate-tools", "page-sandbox.js"), _jsf28)
    _f28 = os.path.join(_dv28, "d.js")
    with open(_f28, "w", encoding="utf-8", errors="surrogatepass") as _f:
        _f.write(_drv28)
    _r28 = subprocess.run(["node", _f28], capture_output=True, timeout=120)
    try:
        _o28 = json.loads(_r28.stdout.decode("utf-8", "replace") or "{}")
    except Exception:
        _o28 = {}
    check(_o28.get("running") == ["lbbusy+lbrun", "lbbusy+lbrun"] and _o28.get("stopping") == ["lbbusy+lbstop", "lbbusy+lbstop"]
          and _o28.get("nextPoll") == ["lbbusy+lbstop", "lbbusy+lbstop"] and _o28.get("afterBeat") == ["dormant", "dormant"],
          "run: the SG and TTS buttons stop by ONE rule - red while stopping, still red on the next poll after a "
          "fast stop, dormant one beat later; the SG button had its own copy and the TTS button none",
          str(_o28)[:220] + _r28.stderr.decode()[:100])
    check(_o28.get("refusedSays") is True and _o28.get("saidOnce") is True and _o28.get("otherError") is True
          and _o28.get("clickClears") is True,
          "run: a browser that refuses sound (NotAllowedError) is SAID - a banner on the page and one line in the "
          "error log - instead of the line being dropped in silence; another failure is not dressed as that; "
          "the first click unlocks sound and clears the banner")
except Exception as _e28:
    check(False, "the patch28 page run did not RUN", str(_e28)[:140])
_ta28 = seg(JS, "async function terminateAll(btn) {", 'const r = await post("/api/terminate", {});')
check('if (hadSong && !songBusy) { songBusy = "stop"; syncSongButton(); }' in _ta28
      and 'if (hadTts && !ttsBusy) { ttsBusy = "stop"; ttsRepaint(); }' in _ta28
      and 'lbs = lbHoldTerm("llm", lbs, fleetWatch);' in JS and 's = lbHoldTerm("tts", s, syncTtsButton);' in JS,
      "Terminate marks the song server as stopping exactly as it marks the TTS server, and all three buttons "
      "take their stop light from the one shared rule")
check('au.play().then(() => { SOUND_OK = true; }).catch(e => { if (el2) el2.classList.remove("playing"); soundRefused(e, "a spoken line"); });' in JS
      and 'window.addEventListener(ev, soundUnlock, { capture: true, passive: true });' in JS
      and 'navigator.locks.request("pandorum-page-alive:" + Math.random()' in JS,   # each page its own since patch41
      "the spoken-line player reports a refusal instead of swallowing it; any first click, key or touch unlocks "
      "sound for the page's life; a Web Lock keeps a minimized tab from being frozen")
check("'id=\"tts-ttsPlayerThoughtForce\" onchange=\"saveTts()\"')" in JS,
      "the force-player-thought switch carries no repeated label - the title above names it")

# ---------------------------------------------------------- v3.80 patch29
# The owner's p28 report: scripted Skyrim dialogue still split into boxes. His
# lines ran 9-10 s apart and the window was 6 s, and only PTI records bundled.
# The window is 11 s now, counted from the LAST line of the record before, so
# every line restarts it; and any record where the player is the one speaking -
# PTI, Dialogue, Combat - bundles, while a record from anyone else ends it.
section("v3.80 patch29: the player's lines share a bracket - 11 s from the last line, any record the player speaks in")

try:
    _dv29 = tempfile.mkdtemp()
    _jsf29 = os.path.join(_dv29, "page.js")
    with open(_jsf29, "w", encoding="utf-8", errors="surrogatepass") as _f:
        _f.write(JS)
    _W29 = chr(12336) + chr(65039)
    _SP29 = chr(0x1F5E3) + chr(65039)
    def _hd29(stamp, title, pid):
        return "[%s] * %-15s [1237]     630 /    14          tok  14120 / 249 tps     0.290 sec  %s%d%s" % (stamp, title, chr(0x27E6), pid, chr(0x27E7))
    def _said29(stamp, who, words):
        return "[%s]    %s%s %s %s: %s %s %s" % (stamp, chr(0x251C), chr(0x2500), _SP29, who, _W29, words, _W29)
    _dash29 = chr(10).join([
        _hd29("20:28:43.25", "PTI", 1), _said29("20:28:44.10", "Maxxor", "You're vampires."),
        _hd29("20:28:52.24", "PTI", 2), _said29("20:28:53.00", "Maxxor", "What happens now."),
        _hd29("20:29:02.27", "PTI", 3), _said29("20:29:03.00", "Maxxor", "And if I refuse your gift."),
        # the player speaking in a Dialogue record, 10 s after the last line: same bracket
        _hd29("20:29:13.00", "Dialogue", 4), _said29("20:29:13.10", "Maxxor", "Then we fight."),
        # an NPC answers: its own box, and it ends the player's bracket
        _hd29("20:29:15.00", "Dialogue", 5), _said29("20:29:15.10", "Serana", "So be it."),
        _hd29("20:29:17.00", "Combat", 6), _said29("20:29:17.10", "Maxxor", "For Skyrim!"),
        # 30 s later: a new bracket
        _hd29("20:29:47.00", "PTI", 7),
    ])
    _drv29 = """
const sb = require(%r);
const L = sb.load(%r, ["bundlePlayer", "segGroups", "state"], "  state = { playerName: 'Maxxor', settings: {} };");
const ls = L.F.bundlePlayer(%s).split(String.fromCharCode(10));
const boxes = L.F.segGroups(ls, "dashboard").map(g => g.filter(i => ls[i].indexOf(String.fromCodePoint(0x27E6)) >= 0).map(i => {
  const s = ls[i], a = s.indexOf(String.fromCodePoint(0x27E6)), b = s.indexOf(String.fromCodePoint(0x27E7)); return s.slice(a + 1, b); }));
process.stdout.write(JSON.stringify({ boxes: boxes }));
""" % (os.path.join(ROOT, "gate-tools", "page-sandbox.js"), _jsf29, json.dumps(_dash29))
    _f29 = os.path.join(_dv29, "d.js")
    with open(_f29, "w", encoding="utf-8", errors="surrogatepass") as _f:
        _f.write(_drv29)
    _r29 = subprocess.run(["node", _f29], capture_output=True, timeout=120)
    try:
        _o29 = json.loads(_r29.stdout.decode("utf-8", "replace") or "{}")
    except Exception:
        _o29 = {}
    check(_o29.get("boxes") == [["1", "2", "3", "4"], ["5"], ["6"], ["7"]],
          "run: the player's lines 9 and 10 s apart share one bracket and keep bundling as each new line restarts "
          "the count - the player speaking in a Dialogue record joins it too; an NPC's record ends it and gets its "
          "own box; the player's Combat line after the NPC starts a new bracket; 30 s later is another",
          str(_o29)[:200] + _r29.stderr.decode()[:100])
except Exception as _e29:
    check(False, "the patch29 bundling run did not RUN", str(_e29)[:140])
check("const PLAYER_BUNDLE_S = 11;" in JS and "bundlePti" not in JS and "PTI_BUNDLE_S" not in JS
      and '"playerName": (player_name_setting() or _spk_player[0] or ""),' in py
      and "b.first - a.last <= PLAYER_BUNDLE_S" in JS,
      "the window is 11 s from the last line of the record before, the player is known to the page by name, and "
      "the PTI-only bundler is gone rather than kept beside the new one")

