# ---------------------------------------------------------- v3.80 patch32
# Forced thinking. "Thinking on" only PERMITS a thought - the owner's Goetia (a Gemma 4
# merge) skipped one now and then. Forced pre-writes the model's own thought opener,
# read from the chat template its server reports, as the start of its turn. If the
# thought comes back inside the answer anyway, the proxy moves it out before SkyrimNet
# reads it - a streamed thought would be spoken, a JSON answer would break. A thinking
# call that returns none writes a line naming the call before it: reported, not
# repaired (592) - an ordinary reply's inline thought is left as SkyrimNet got it.
section("v3.80 patch32: forced thinking - the model's own opener, the net on both reply paths, the miss line")

try:
    _keep32 = (fp.urlopen, dict(fp._THINK_MARKS), fp.panel_log, dict(fp._LAST_THINK))
    class _R32(object):
        def __init__(self, b):
            self.b = b
        def read(self):
            return self.b
        def __enter__(self):
            return self
        def __exit__(self, *a):
            return False
    _tpl32 = {"9001": "{{ '<|turn>model' }}{% if not enable_thinking %}{{ '<|channel>thought\\n<channel|>' }}{% endif %}",
              "9002": "{% if enable_thinking %}<think>{% endif %}", "9003": "{{ messages }}"}
    fp.urlopen = lambda req, timeout=0: _R32(json.dumps({"chat_template": _tpl32[req.full_url.split(":")[2].split("/")[0]]}).encode())
    fp._THINK_MARKS.clear()
    _mk32 = [fp.think_markers(p) for p in ("9001", "9002", "9003")]
    def _shape32(port, force, last_role="user"):
        _d = {"messages": [{"role": "system", "content": "s"}, {"role": last_role, "content": "u"}]}
        _rt = {"server": port, "thinking": True, "forceThink": force, "title": "Charbio"}
        fp.apply_route_shape(_d, _rt)
        return _d["messages"][-1], _rt.get("_forced")
    _s1 = _shape32("9001", True); _s2 = _shape32("9002", True); _s3 = _shape32("9003", True)
    _s4 = _shape32("9001", False); _s5 = _shape32("9001", True, "assistant")
    check(_mk32 == [("<|channel>thought\n", "<channel|>"), ("<think>\n", "</think>"), ("", "")]
          and _s1 == ({"role": "assistant", "content": "<|channel>thought\n"}, ("<|channel>thought\n", "<channel|>"))
          and _s2[0] == {"role": "assistant", "content": "<think>\n"}
          and _s3 == ({"role": "user", "content": "u"}, None) and _s4 == ({"role": "user", "content": "u"}, None)
          and _s5[1] is None,
          "run: forced thinking pre-writes the model's OWN opener - <|channel>thought for a Gemma 4 template, <think> "
          "for a think template, read from what the server reports - and a template with neither is not forced; "
          "off, nothing is added; a request that already ends with the model's turn is left alone",
          str((_mk32, _s1, _s3))[:220])
    _fs32 = [fp.force_split("weigh the bio<channel|>\n{\"a\":1}", "<|channel>thought\n", "<channel|>"),
             fp.force_split("<|channel>thought\nweigh it<channel|>{\"a\":1}", "<|channel>thought\n", "<channel|>"),
             fp.force_split("{\"a\":1}", "<|channel>thought\n", "<channel|>")]
    _fz32 = fp._ForcedStream("<|channel>thought\n", "<channel|>")
    _sent32 = []
    for _pc in ["weigh the bio ", "first<chan", "nel|>{\"a\":", "1}"]:
        _o = {"choices": [{"delta": {"content": _pc}}]}
        _outs, _a, _t = _fz32.feed(_o, b"data: " + json.dumps({"choices": [{"delta": {"content": _pc}}]}).encode() + b"\n")
        _sent32 += [l for l in _outs if l.startswith(b"data: ")]
    _kinds32 = [list(json.loads(l[6:])["choices"][0]["delta"].items())[0] for l in _sent32]
    _ans32 = "".join(v for k, v in _kinds32 if k == "content")
    _th32 = "".join(v for k, v in _kinds32 if k == "reasoning_content")
    _fz32b = fp._ForcedStream("<|channel>thought\n", "<channel|>")
    _pass32 = (_fz32b.feed({"choices": [{"delta": {"reasoning_content": "r"}}]}, b"L1")[0],
               _fz32b.feed({"choices": [{"delta": {"content": "answer"}}]}, b"L2")[0])
    check(_fs32 == [('{"a":1}', "weigh the bio"), ('{"a":1}', "weigh it"), ('{"a":1}', "")]
          and _ans32 == '{"a":1}' and _th32 == "weigh the bio first" and _pass32 == ([b"L1"], [b"L2"]),
          "run: a forced thought that comes back inside the answer is moved out - whole replies and streams alike, "
          "the closing marker found even when a chunk cuts it in two - so SkyrimNet gets the answer alone; a server "
          "that separates the thought itself is left untouched",
          str((_fs32, _ans32, _th32))[:200])
    _logs32 = []
    fp.panel_log = lambda m: _logs32.append(m)
    fp._LAST_THINK.update(title="", asked=False, got=False)
    fp.note_think_outcome({"title": "Charbio", "thinking": True}, "a thought")
    fp.note_think_outcome({"title": "Charbio", "thinking": True}, "")
    fp.note_think_outcome({"title": "Meta", "thinking": False}, "")
    check(_logs32 == ["[proxy] Charbio asked for thinking and none came back - the call before: Charbio, which asked for thinking and got it"]
          and fp._split_think("<|channel>thought\nweigh it<channel|>{\"a\":1}") == ('{"a":1}', "weigh it"),
          "run: a call that asked for thinking and got none writes one line naming the call before it - the owner's "
          "consecutive-call pattern becomes a count; a call that did not ask writes nothing; Gemma 4's channel is "
          "read as a thought wherever the panel splits one out")
finally:
    try:
        fp.urlopen = _keep32[0]; fp._THINK_MARKS.clear(); fp._THINK_MARKS.update(_keep32[1])
        fp.panel_log = _keep32[2]; fp._LAST_THINK.clear(); fp._LAST_THINK.update(_keep32[3])
    except NameError:
        pass
_ns32 = seg(py, "data = resp.read(); ms = round((time.monotonic() - t0) * 1000)", "self._send_head(resp, streaming=False)")
check("_ans, _th = force_split(_m.get(\"content\") or \"\", *rt[\"_forced\"])" in _ns32
      # and the split is APPLIED to what is sent - finding the call alone let a disabled net through
      # (patch32's own control)
      and "if _th:\r\n                                _m[\"content\"], _m[\"reasoning_content\"] = _ans, _th\r\n" in _ns32
      and "data = json.dumps(_j, ensure_ascii=False).encode(\"utf-8\")" in _ns32
      and "_fz = _ForcedStream(*rt[\"_forced\"]) if rt.get(\"_forced\") else None" in py
      and "outs, _a, _t = _fz.feed(obj, line)" in py
      # the proxy REPORTS a missing thought; it does not split an inline one out of an ordinary
      # reply - the record shows what SkyrimNet received (gotcha 592, as hotfix6 left it)
      and "_inl" not in seg(py, "def _proxy(self)", "def _background_init")
      and py.count("note_think_outcome(rt, ") - py.count("def note_think_outcome(rt, ") == 2   # the calls, not the def
      and '"forceThink": bool(p.get("forceThink")) and slot_reasoning(slot) != "off",' in py
      and '"thinking": bool(p.get("thinking") or p.get("forceThink")) and slot_reasoning(slot) != "off",' in py
      and 'if "forceThink" in body:' in py,
      "the whole-reply net runs BEFORE the reply is sent, the stream net rewrites each chunk before it is written, "
      "both paths note the outcome - reported, not repaired (592), and the switch travels from the card to the route")
check('data-field="forceThink"' in JS and "Forced thinking" in JS
      # since patch33 Thinking also locks when the server's Reasoning dial is off
      and "((p.forceThink || rzOff) ? ' disabled' : '')" in JS
      and "(p.forceThink ? '<span style=\"opacity:.45\" title=\"Forced thinking is on - it replaces this switch\">' : '')" in JS
      and 'data-t="\' + pgSlug("Forced thinking") + \'"' in JS
      and "{ name:\"Forced thinking\"," in JS,
      "the provider card carries Forced thinking below Thinking, greys and locks Thinking while it is on, and links "
      "to the Sampler Guide's own Forced thinking entry")

# ---------------------------------------------------------- v3.80 patch33
# The owner's report: the provider slot's DRY menu showed its flags in the link colour
