# ---------------------------------------------------------- v3.80 patch52
# patch51's watcher ended in its first seconds: it quit on any state but "loading", and the
# port probe says "none" until the server binds its port. The owner refreshed again. The watch
# now keys on the process - alive and not yet serving - and pushes when it serves or dies.
section("v3.80 patch52: the watcher rides the probe's run-up and ends on serving or death")

_keep52 = (fp.song_server_status, fp.sse_notify, dict(fp.SONG_PROC), fp.time.sleep)
try:
    fp.time.sleep = lambda s: None
    class _P52(object):
        def __init__(self):
            self.rc = None
        def poll(self):
            return self.rc
    def _run52(states, die_at=None):
        _polls, _pushes, _it, _p = [], [], iter(states), _P52()
        def _status(*a, **k):
            _polls.append(1)
            if die_at is not None and len(_polls) >= die_at:
                _p.rc = 1
            return {"state": next(_it)}
        fp.song_server_status = _status
        fp.sse_notify = lambda kind, extra=None, scope=None: _pushes.append(kind)
        fp.SONG_PROC.update(pid=77, proc=_p)
        fp.song_server_watch(77)
        return len(_polls), list(_pushes)
    _late52 = _run52(["none", "none", "waiting", "loading", "serving", "serving"])
    _died52 = _run52(["none", "none", "none", "none", "none"], die_at=3)
finally:
    fp.song_server_status, fp.sse_notify = _keep52[0], _keep52[1]
    fp.SONG_PROC.clear(); fp.SONG_PROC.update(_keep52[2]); fp.time.sleep = _keep52[3]
check(_late52 == (5, ["state"]) and _died52 == (3, ["state"])
      and 'if st.get("state") == "serving" or proc is None or proc.poll() is not None:' in py
      and 'if st.get("state") != "loading":\r\n            sse_notify("state")' not in py,
      "run: the watcher rides the probe's none, none, waiting and loading and pushes once at serving; a server that "
      "dies while loading is pushed once too; no interim name ends the watch", str((_late52, _died52))[:80])

