# ---------------------------------------------------------- v3.91 patch1
# Decision Models > Diagnostics: every typed target decision is set against the cues SkyrimNet sent
# with it, kept per session in the log folder (the newest 50 of each selector) and read back as two
# cards, Player Target Selector and NPC Target Selector, with a drawer tab per model; Compile report
# writes one Markdown report per selector with every case for review and its exchange. The records
# are made after the answer has gone. And the page reads its state once at a time, the server builds
# it once for everyone waiting, a background refresh leaves an unchanged pane alone, and a held
# button holds the refresh. Folder Settings and Customization keep the running gear off their card.
section("v3.91 patch1: target diagnostics; one state read at a time; a press holds the refresh")


def _p1_people(rows):
    return "\n\n".join("%s (%s, %.2fm away)%s\n-\n%s is described here." % (n, race, d, "".join(" [%s]" % f for f in fl), n)
                       for n, race, d, fl in rows)


_P1_NEAR = [("Lydia", "Female Nord", 1.20, ["COMPANION"]), ("Faendal", "Male Bosmer", 2.40, []),
            ("Camilla", "Female Imperial", 3.10, []), ("Hulda", "Female Nord", 9.00, [])]
_P1_RECENT = "\n".join([
    "- [9:00 PM, Middas] (dialogue) Lydia to Faendal: First line.",
    "- [9:00 PM, Middas] (npc_thoughts) Lydia: A thought that is not a chat line.",
    "- [9:01 PM, Middas] (dialogue) Faendal to Lydia: Second line.",
    "- [9:01 PM, Middas] [Now at Whiterun] (dialogue) Lydia to Faendal: Third line.",
    "- [9:02 PM, Middas] (dialogue_background) Hero: (Heavy breathing - sprinting)",
    "- [9:02 PM, Middas] (dialogue) Faendal to Lydia: Fourth line.",
    "- [9:03 PM, Middas] (dialogue) Lydia to Faendal: Fifth line.",
    "- [9:03 PM, Middas] (dialogue) Faendal to Lydia: Sixth line.",
])


def _p1_target(looking, line, last, choice, probs=None, err=None):
    names = [n for n, *_ in _P1_NEAR]
    crit = {"none": "Nobody answers."}
    for i, n in enumerate(names, 1):
        crit["s%d_tplayer" % i] = "Hero is speaking to %s, who answers Hero" % n
        for j, m in enumerate(names, 1):
            if j != i:
                crit["s%d_t%d" % (i, j)] = "Hero is asking %s to speak to %s" % (n, m)
    recent = _P1_RECENT + "\n- [9:04 PM, Middas] (dialogue_player_text) Hero: " + line
    req = {"model": "Server 2", "questions": {"target": {"type": "choice", "criteria": json.dumps(crit),
                                                       "instructions": "Decide who Hero is speaking to in `player_line`."}},
           "state": {"nearby": _p1_people(_P1_NEAR), "looking_at": looking, "player_line": "Hero: " + line,
                     "last_exchange": last, "recent_dialogue": recent, "location": "Whiterun"}}
    if err:
        return req, {"error": {"code": 400, "message": err}}
    pr = dict(probs or {})
    pr.setdefault(choice, 0.70)
    for k in crit:
        pr.setdefault(k, 0.01)
    return req, {"answers": {"target": {"type": "choice", "choice": choice, "probabilities": pr}}}


_P1_CANDS = [("Lydia", "Female Nord", 1.50, ["COMPANION", "ENGAGED"]), ("Faendal", "Male Bosmer", 2.00, []),
             ("Camilla", "Female Imperial", 4.00, [])]


def _p1_speaker(last, lastline, choice, probs=None, err=None):
    names = [n for n, *_ in _P1_CANDS]
    crit = {"none": "No one speaks. The conversation pauses or ends here."}
    for i, (n, _r, _d, fl) in enumerate(_P1_CANDS, 1):
        tag = "".join(" [%s]" % f for f in fl)
        crit["s%d_tplayer" % i] = "%s%s speaks to Hero" % (n, tag)
        for j, m in enumerate(names, 1):
            if j != i:
                crit["s%d_t%d" % (i, j)] = "%s%s speaks to %s" % (n, tag, m)
    recent = _P1_RECENT + "\n- [9:05 PM, Middas] (dialogue) " + lastline \
        + "\n- [9:05 PM, Middas] (npc_thoughts) Camilla: Not a chat line." \
        + "\n- [9:05 PM, Middas] (death) Wolf: Wolf was killed by Hero"
    req = {"model": "Server 2", "questions": {"speaker": {"type": "choice", "criteria": json.dumps(crit),
                                                        "instructions": "Decide who speaks next and to whom."}},
           "state": {"candidates": _p1_people(_P1_CANDS), "last_exchange": last, "recent_dialogue": recent,
                     "player": "Hero. The player is freely exploring the world.", "location": "Whiterun"}}
    if err:
        return req, {"error": {"code": 400, "message": err}}
    pr = dict(probs or {})
    pr.setdefault(choice, 0.60)
    for k in crit:
        pr.setdefault(k, 0.01)
    return req, {"answers": {"speaker": {"type": "choice", "choice": choice, "probabilities": pr}}}


