# --- api_settings: the peer slots and the trust, validated before anything is saved
class _Saved2(Exception):
    pass
def _p2_settings(cfg, body):
    _keep = (fp.load_config, fp.save_config)
    def _save(c):
        raise _Saved2(c)
    fp.load_config = lambda *a, **k: json.loads(json.dumps(cfg))
    fp.save_config = _save
    try:
        return fp.api_settings(body)
    except _Saved2 as s:
        return {"saved": s.args[0]["settings"]}
    finally:
        fp.load_config, fp.save_config = _keep
