def _v3(head, tie, layers=4, found=4, missing=(), embed=True):
    f = {"head": head, "tie": tie, "layers": layers, "layersFound": found, "missing": list(missing), "embed": embed, "files": "safetensors", "why": ""}
    return fp._hub_verdict(f)
