section("v3.91 patch4: Hub > LLM's genuine integrity read, its columns and sort, the card in its own frame, the HF model tree, wide server cards")

# --- a stand-in for Hugging Face, under the panel's own opener: every read below goes the real way -
# _hi_get's host check, the read cache, the ranged reads - and only the bytes are made up
import struct as _s4
from urllib.parse import urlparse as _up4, parse_qs as _pq4, unquote as _uq4
_V4, _H4 = 64, 256

def _bf4(salt, n):
    return b"".join(_s4.pack("<f", ((i * 31 + salt * 17) % 200 - 100) / 1000.0)[2:4] for i in range(n))

def _st4(ts):
    hdr, off, blob = {}, 0, b""
    for nm, shp, data in ts:
        hdr[nm] = {"dtype": "BF16", "shape": shp, "data_offsets": [off, off + len(data)]}
        off += len(data)
        blob += data
    hj = json.dumps(hdr).encode()
    return _s4.pack("<Q", len(hj)) + hj + blob

def _model4(head="own", tie=True, g4="root", experts=4, ple=True):
    p = "model.language_model."
    emb = b"".join(_bf4(r, _H4) for r in range(_V4))
    ts = [(p + "embed_tokens.weight", [_V4, _H4], emb)]
    for i in range(4):
        hd, rows = (64, 128) if i == 3 else (32, 256)
        ts += [(p + "layers.%d.self_attn.k_proj.weight" % i, [rows, _H4], b"\0" * rows * _H4 * 2),
               (p + "layers.%d.self_attn.k_norm.weight" % i, [hd], b"\0" * hd * 2),
               (p + "layers.%d.mlp.down_proj.weight" % i, [_H4, 96], b"\0" * _H4 * 96 * 2)]
        if experts:
            ts.append((p + "layers.%d.mlp.router.proj.weight" % i, [experts, _H4], b"\0" * experts * _H4 * 2))
    if ple:
        ts.append((p + "embed_tokens_per_layer.weight", [_V4, 512], b"\0" * _V4 * 512 * 2))
    ts.append(("model.vision_tower.encoder.layers.0.w", [8, 8], b"\0" * 128))
    if head == "own":
        ts.append(("lm_head.weight", [_V4, _H4], b"".join(_bf4(r + 999, _H4) for r in range(_V4))))
    elif head == "copy":
        ts.append(("lm_head.weight", [_V4, _H4], emb))
    shards = {"model-00001-of-00002.safetensors": _st4(ts[0::2]), "model-00002-of-00002.safetensors": _st4(ts[1::2])}
    wm = {nm: ("model-00001-of-00002.safetensors" if k % 2 == 0 else "model-00002-of-00002.safetensors") for k, (nm, _s, _d) in enumerate(ts)}
    tc = {"model_type": "gemma4_text", "num_hidden_layers": 4, "hidden_size": _H4, "vocab_size": _V4, "intermediate_size": 96}
    if experts:
        tc.update(num_experts=experts, top_k_experts=2)
    if tie is not None:
        tc["tie_word_embeddings"] = tie
    cfg = {"model_type": "gemma4", "architectures": ["Gemma4ForConditionalGeneration"], "text_config": tc, "vision_config": {"num_hidden_layers": 1}}
    if g4 == "root":
        cfg.update(global_head_dim=512, num_global_key_value_heads=2)
    elif g4 == "text_config":
        tc.update(global_head_dim=512, num_global_key_value_heads=2)
    total = sum(len(d) for _n, _s, d in ts)
    return shards, {"metadata": {"total_size": total}, "weight_map": wm}, cfg

def _gguf4(head=True, hckv_array=True, embt=12, outt=14):
    def s(x):
        b = x.encode()
        return _s4.pack("<Q", len(b)) + b
    kv = [s("general.architecture") + _s4.pack("<I", 8) + s("gemma4"), s("gemma4.block_count") + _s4.pack("<I", 4) + _s4.pack("<I", 4)]
    kv.append(s("gemma4.attention.head_count_kv") + (_s4.pack("<I", 9) + _s4.pack("<I", 4) + _s4.pack("<Q", 4) + _s4.pack("<4I", 8, 8, 8, 2)
                                                    if hckv_array else _s4.pack("<I", 4) + _s4.pack("<I", 8)))
    kv.append(s("tokenizer.ggml.tokens") + _s4.pack("<I", 9) + _s4.pack("<I", 8) + _s4.pack("<Q", 3) + s("a") + s("b") + s("c"))
    names = [("token_embd.weight", embt)] + [("blk.%d.attn_q.weight" % i, 12) for i in range(4)] + ([("output.weight", outt)] if head else [])
    ti = b"".join(s(n) + _s4.pack("<I", 2) + _s4.pack("<QQ", 4, 8) + _s4.pack("<I", t) + _s4.pack("<Q", 0) for n, t in names)
    return b"GGUF" + _s4.pack("<I", 3) + _s4.pack("<Q", len(names)) + _s4.pack("<Q", len(kv)) + b"".join(kv) + ti + b"\0" * 32

