class _R4(io.BytesIO):
    def __init__(self, b, status=200, headers=None):
        super().__init__(b)
        self.status, self.code, self.headers = status, status, dict(headers or {})
    def close(self):
        pass

def _info4(rid):
    if rid in _REPOS4:
        sh, ix, _c = _REPOS4[rid]
        sib = [{"rfilename": "config.json", "size": 900}, {"rfilename": "model.safetensors.index.json", "size": 500}]
        sib += [{"rfilename": n, "size": len(b) // (3 if rid == "g4/Short" and n.startswith("model-00001") else 1), "lfs": {"sha256": "ab" * 32}}
                for n, b in sorted(sh.items())]
        return {"id": rid, "tags": _TAGS4.get(rid, []), "siblings": sib, "lastModified": "2026-10-01T00:00:00.000Z", "safetensors": {"total": 26e9}}
    if rid == "q/Own-GGUF":
        return {"id": rid, "tags": ["gguf"], "siblings": [{"rfilename": n, "size": len(b), "lfs": {"sha256": "cd" * 32}} for n, b in _GG4.items()]}
    return {"id": rid, "tags": _TAGS4.get(rid, []), "siblings": []}

class _Op4(object):
    def open(self, req, timeout=None):
        url = req.full_url
        rng = req.get_header("Range") or ""
        _media4.setdefault("asked", []).append((url, rng))
        u = _up4(url)
        path, q = _uq4(u.path), _pq4(u.query)
        if path == "/api/models":
            fl = q.get("filter", [])
            rel = next((x for x in fl if x.startswith("base_model:")), "")
            hits = {"base_model:merge:g4/Base-it": [{"id": "g4/Own"}, {"id": "g4/Copy"}],
                    "base_model:quantized:g4/Own": [{"id": "q/Own-GGUF", "tags": ["gguf"], "downloads": 5}]}.get(rel, [])
            return _R4(json.dumps(hits).encode())
        m = re.match(r"^/api/models/([^/]+/[^/]+)$", path)
        if m:
            return _R4(json.dumps(_info4(m.group(1))).encode())
        m = re.match(r"^/([^/]+/[^/]+)/resolve/main/(.+)$", path)
        if not m:
            raise HTTPError(url, 404, "Not Found", {}, None)
        rid, f = m.group(1), m.group(2)
        if f.endswith(".mp4"):
            data = b"\0\0\0\x18ftypmp42" + b"v" * 1000
        elif rid in _REPOS4 and f == "config.json":
            data = json.dumps(_REPOS4[rid][2]).encode()
        elif rid in _REPOS4 and f == "model.safetensors.index.json":
            data = json.dumps(_REPOS4[rid][1]).encode()
        elif rid in _REPOS4 and f in _REPOS4[rid][0]:
            data = _REPOS4[rid][0][f]
        elif f in _GG4:
            data = _GG4[f]
        else:
            raise HTTPError(url, 404, "Not Found", {}, None)
        if rng:
            a, b = rng.split("=")[1].split("-")
            a, b = int(a or 0), (int(b) if b else len(data) - 1)
            part = data[a:b + 1]
            return _R4(part, 206, {"Content-Length": str(len(part)), "Content-Range": "bytes %d-%d/%d" % (a, a + len(part) - 1, len(data))})
        return _R4(data, 200, {"Content-Length": str(len(data))})

