section("v3.76 patch24: the terminal differ runs, and can say no")

_tdf = os.path.join(ROOT, "gate-tools", "term-diff.js")
if not os.path.isfile(_tdf):
    check(False, "the terminal differ is in the tree", "gate-tools/term-diff.js")
elif shutil.which("node") is None:
    check(None, "run: the differ paints five terminals", "node not installed")
else:
    # requires stay relative: an absolute path is a working directory published as
    # a dependency, and it holds for exactly one container by construction
    # written with chr(): a quote inside a quote inside this file is how the pin
    # itself broke twice before it first ran (gotcha 2, python side)
    _absreq = re.compile("require[(]\\s*[" + chr(34) + chr(39) + "](/|[A-Za-z]:)")
    for _fn24 in sorted(os.listdir(os.path.join(ROOT, "gate-tools"))):
        if not _fn24.endswith(".js"):
            continue
        _rel24 = "gate-tools/" + _fn24
        _n24 = len(_absreq.findall(rd(_rel24).decode("utf-8", "replace")))
        check(_n24 == 0, "%s requires by relative path only" % _rel24,
              "%d absolute require(s)" % _n24)
    check(bool(_absreq.search("require(" + chr(34) + "/home/x/y.js" + chr(34) + ")")),
          "control: the relative-path pin matches a planted offender")
    _tdd = os.path.dirname(jsf)
    _tdc = os.path.join(_tdd, "td-corpus.txt")
    with open(_tdc, "w", encoding="utf-8", newline="") as _f24:
        _f24.write("[12:34:56.78] " + chr(0x1F4AC) + " Dialogue        [8081]"
                   "  9313 /    67 tok  2990 /  77 tps  4.223 sec\n"
                   "  " + chr(0x1F3AD) + " Brelyna Maryon: " + chr(0x3030) + chr(0xFE0F)
                   + "So you made it, *smiles* good." + chr(0x3030) + chr(0xFE0F)
                   + " (4.42x)\n"
                   "  prep: 118ms  server: 902ms  audio: 3.41s 4.42x\n")
    _anch24 = 'stamp:  "#4dd8e6",'
    check(JS.count(_anch24) == 1, "the perturbation anchor exists once in the page",
          "count=%d" % JS.count(_anch24))
    _pjs24 = os.path.join(_tdd, "page-perturbed.js")
    open(_pjs24, "wb").write(JS.replace(_anch24, 'stamp:  "#123456",', 1)
                             .encode("utf-8", "surrogatepass"))
    for _t24 in ("dashboard", "thinking", "ptipme", "ttscal", "tts"):
        _rr24 = subprocess.run(["node", _tdf, jsf, jsf, _t24, _tdc],
                               capture_output=True, text=True, timeout=180)
        check(_rr24.returncode == 0 and "identical" in _rr24.stdout,
              "self against self is identical on %s and exits 0" % _t24,
              (_rr24.stdout + _rr24.stderr).strip()[:200])
    _rr24 = subprocess.run(["node", _tdf, jsf, jsf, "dashboard", _tdc, "--lines"],
                           capture_output=True, text=True, timeout=180)
    check(_rr24.returncode == 0 and "0 painted differently" in _rr24.stdout,
          "the per-line diagnosis mode still runs and exits 0",
          (_rr24.stdout + _rr24.stderr).strip()[:200])
    _rr24 = subprocess.run(["node", _tdf, jsf, _pjs24, "dashboard", _tdc],
                           capture_output=True, text=True, timeout=180)
    check(_rr24.returncode == 1 and "DIFFERENT" in _rr24.stdout,
          "control: one moved colour is reported DIFFERENT and exits 1",
          "rc=%d %s" % (_rr24.returncode, (_rr24.stdout + _rr24.stderr).strip()[:160]))


